/**
 * @dsh-external/dsh-novel-script —— 浏览器半边。
 *
 * 三个挂点，都是"加在旁边"而不是"替换"：
 *   1. `sidebar.footer.action`     —— 侧栏底部、和「设置」同排的常驻入口（任何状态都在）；
 *   2. `shell.overlay`             —— 全屏浮层（工作台住在这里）；
 *   3. `conversation.session.header.actions` —— 会话标题栏上的「剧本批注」（会话开始后出现）。
 *
 * ⚠️ 不注册 `main` / `main.conversation`：那是官方对话区的**单占席位**，
 *    注册进去就是替换掉它。这里要的是"浮在官方界面之上"，官方对话一个像素不动。
 *
 * ⚠️ `shell.overlay` 这一层是 **click-through** 的：浮层根元素必须
 *    `pointer-events: none`，面板自己 `auto`；两处都要写，写错就是"整屏点不动"。
 */

import { Component, useEffect, useState, type ReactNode } from 'react'
import { OVERLAY_SLOT, PANEL_ID } from '../shared/protocol.ts'
import { Workbench } from './Workbench.tsx'
import { overlayCss } from './styles.ts'
import { hasUnsaved } from './unsaved.ts'
import type { WorkspaceFilesFace } from './workspace.ts'

/** `ctx.slots` 的最小面。 */
interface SlotsFace {
  inject(key: string, callback: () => unknown): () => void
  register(
    options: Record<string, unknown> & { order?: string | number },
    component: (props: never) => ReactNode,
  ): () => void
}

/** `ctx.sessions` 的最小面（读"当前会话"）。 */
interface SessionsService {
  list: {
    getSnapshot(): { current?: string }
    subscribe(listener: () => void): () => void
  }
}

/** `ctx.workspaces` 的最小面（没有当前会话时兜一个）。 */
interface WorkspacesService {
  list: {
    getSnapshot(): {
      items: ReadonlyArray<{
        workspaceId: string
        path: string
        title: string
        sessionIds: readonly string[]
      }>
    }
    subscribe(listener: () => void): () => void
  }
}

interface ClientContext {
  slots: SlotsFace
  remote: { workspaceFiles: WorkspaceFilesFace }
  sessions: SessionsService
  workspaces: WorkspacesService
  effect(fn: () => void | (() => void), label?: string): void
}

/**
 * 依赖声明。
 *
 * `remote.workspaceFiles` 是**官方**的 Remote 命名空间（list / read / …），
 * 用来读工作区里的文件 —— 只读，够用。写批注走插件自己在宿主注册的
 * `/api/novel-script/annotations`（见 src/index.ts）。
 */
export const inject = ['slots', 'remote', 'remote.workspaceFiles', 'sessions', 'workspaces']

/**
 * 给挂点组件用的外部句柄。
 *
 * 为什么用模块级变量：`ctx.*` 只在 `apply` 的闭包里拿得到，而挂点组件是普通组件
 * （`shell.overlay` 这个席位不挂 hook 上下文，拿不到 `useSessions` 之类的标准 prop）。
 */
const handles: {
  files?: WorkspaceFilesFace
  session?: { get(): string | undefined; subscribe(fn: () => void): () => void }
  workspaces?: {
    get(): { items: ReadonlyArray<{ workspaceId: string; path: string; title: string; sessionIds: readonly string[] }> }
    subscribe(fn: () => void): () => void
  }
} = {}

/* ── 开/关状态（模块级小 store，避免依赖席位注入的 hook）────────────────── */
const listeners = new Set<() => void>()
let open = false
function setOpen(next: boolean): void {
  open = next
  for (const listener of listeners) listener()
}

/** 订阅开/关状态。 */
function useOpen(): boolean {
  const [, force] = useState(0)
  useEffect(() => {
    const listener = (): void => force(n => n + 1)
    listeners.add(listener)
    return () => { listeners.delete(listener) }
  }, [])
  return open
}

/**
 * 开关工作台。
 *
 * ⚠️ 关之前要问一句：人工编辑模式里可能有**没保存的改动**，而浮层一关，
 *    工作台组件就卸载了，草稿跟着没（草稿只在内存里，磁盘上一个字都没写）。
 *    有没有改动由工作台通过 `unsaved.ts` 那个小开关告诉这里。
 */
function toggleOpen(next: boolean): void {
  if (!next && hasUnsaved() && !window.confirm('工作台里还有没保存的人工改动，关掉就丢了。确定关掉吗？')) return
  setOpen(next)
}

export function apply(ctx: ClientContext): void {
  console.info('[novel-script] client apply: start')
  handles.files = ctx.remote.workspaceFiles
  handles.session = {
    get: () => ctx.sessions.list.getSnapshot().current,
    subscribe: fn => ctx.sessions.list.subscribe(fn),
  }
  handles.workspaces = {
    get: () => ctx.workspaces.list.getSnapshot(),
    subscribe: fn => ctx.workspaces.list.subscribe(fn),
  }

  /* 样式：一次插入，随插件卸载自动移除。 */
  ctx.effect(() => {
    const tag = document.createElement('style')
    tag.setAttribute('data-novel-script', 'workbench')
    tag.textContent = overlayCss
    document.head.append(tag)
    return (): void => { tag.remove() }
  }, 'novel-script: styles')

  /* 1. 侧栏底部、「设置」上面那一排的入口（和设置同级别的常驻按钮）。
        ⚠️ 为什么不放侧栏最上方（`sidebar.panellist`）：主人说那枚图标"没什么用"，
        要的是和设置摆在一起的常驻入口。官方给这个位置留的席位就是
        `sidebar.footer.action`（"Optional actions beside Settings at the sidebar foot"）。 */
  ctx.slots.inject('sidebar.footer.action', () =>
    ctx.slots.register({ name: 'sidebar.footer.action', id: 'novel-script-open', order: 10, label: '剧本批注' }, FooterAction))

  /* 2. 全屏浮层（工作台） */
  ctx.slots.inject(OVERLAY_SLOT, () =>
    ctx.slots.register({ name: OVERLAY_SLOT, id: PANEL_ID, order: 50, label: '剧本批注' }, NovelScriptOverlay))

  /* 3. 会话标题栏上的入口（`conversation.session.header.actions`）。
        ⚠️ 已知局限：刚开的新会话是"空白会话"状态，标题栏还没渲染，
        这个按钮**要等会话真正开始**才出现（侧栏那枚图标是任何状态下都在的）。
        换别的挂点的事正在和主人确认，别自己挪。 */
  ctx.slots.inject('conversation.session.header.actions', () =>
    ctx.slots.register({ name: 'conversation.session.header.actions', id: 'novel-script-open', order: 80, label: '剧本批注' }, OpenWorkbenchButton))

  console.info('[novel-script] client apply: slots registered')
}

/**
 * 侧栏底部、「设置」上面那一排的常驻入口。
 *
 * ⚠️ 外观必须和「设置」那一行一致：几何照抄 DSH 的 `SettingsTrigger`（见 styles.ts
 * 里 `.ns-foot` 的注释）。`sidebar.footer.action` 的契约是"每个占位者自己负责
 * 按钮几何与 hover 样式"，所以这里要自己写全，别指望容器给。
 *
 * 席位会把 `wide` 传进来（侧栏展开/收起），收起时只留图标 —— 和设置那一行一样。
 */
function FooterAction({ wide = true }: { wide?: boolean }): ReactNode {
  const isOpen = useOpen()
  return (
    <button
      type="button"
      className={`ns-foot${wide ? '' : ' ns-foot-rail'}${isOpen ? ' ns-foot-on' : ''}`}
      title={isOpen ? '收起剧本批注工作台' : '打开剧本批注工作台'}
      aria-label="剧本批注"
      aria-pressed={isOpen}
      onClick={() => toggleOpen(!isOpen)}
    >
      {/* 剧本图标：一页纸 + 一道折角，SVG 画，不依赖字体 */}
      <svg width={wide ? 16 : 18} height={wide ? 16 : 18} viewBox="0 0 16 16" fill="none" aria-hidden>
        <path d="M4.5 1.5h5L13 5v9.5H4.5z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />
        <path d="M9.3 1.6V5h3.5" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />
        <path d="M6.3 8.4h4M6.3 11h2.6" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" />
      </svg>
      {wide ? <span className="ns-foot-label">剧本批注</span> : null}
    </button>
  )
}

/**
 * 输入框工具条上的「剧本批注」按钮。
 *
 * 它自报状态（不靠 hover 猜）：打开着就高亮。点开看到的是工作台，
 * 没登记的工作区里是一张"还没登记 + 可复制的指令"的卡，不会点了没反应。
 */
function OpenWorkbenchButton(): ReactNode {
  const isOpen = useOpen()
  return (
    <button
      type="button"
      className={`ns-chip${isOpen ? ' ns-chip-on' : ''}`}
      title={isOpen ? '收起剧本批注工作台' : '打开剧本批注工作台'}
      aria-pressed={isOpen}
      onClick={() => toggleOpen(!isOpen)}
    >
      <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden>
        <path d="M4.5 1.5h5L13 5v9.5H4.5z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />
        <path d="M9.3 1.6V5h3.5" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />
      </svg>
      <span>剧本批注</span>
    </button>
  )
}

/** 全屏浮层。 */
function NovelScriptOverlay(): ReactNode {
  const isOpen = useOpen()
  const session = useSessionId()
  if (!isOpen) return null
  return (
    /* 根层：none —— 空白处穿透到官方界面（对话区、输入框照常可点） */
    <div className="ns-root" style={{ pointerEvents: 'none' }}>
      {/* 面板自己：auto（内联写，双保险 —— CSS 万一丢了也不会整屏点不动） */}
      <div style={{ pointerEvents: 'auto', display: 'contents' }}>
        <OverlayBoundary>
          <Workbench files={handles.files} sessionId={session.id} sessionSource={session.source} />
        </OverlayBoundary>
      </div>
    </div>
  )
}

/**
 * 浮层的错误边界。
 *
 * ⚠️ 为什么必须有（2026-09-14 踩过）：工作台里任何一处抛异常（当时是
 *    宿主返回老格式批注、客户端读 `a.regions[0]`），React 会把整棵子树卸掉 ——
 *    表现是**点了图标浮窗什么都不出来**，而且看不出原因。有这个边界，
 *    至少会把错误原文显示出来，能自查也能直接复制给开发者。
 */
class OverlayBoundary extends Component<{ children: ReactNode }, { error: string }> {
  override state = { error: '' }

  static getDerivedStateFromError(error: unknown): { error: string } {
    return { error: error instanceof Error ? error.message : String(error) }
  }

  override render(): ReactNode {
    if (this.state.error !== '') {
      return (
        <div className="ns-root" style={{ pointerEvents: 'none' }}>
          <div
            className="ns-workbench"
            style={{ left: 24, top: 80, width: 460, height: 'auto', pointerEvents: 'auto' }}
          >
            <div className="ns-wb-hd"><span className="ns-t">剧本批注</span></div>
            <div className="ns-empty">
              工作台出错了（内容没渲染出来）：
              <br />
              {this.state.error}
              <br />
              <br />
              先刷新页面；如果反复出现，把上面这句话发给开发者。
            </div>
          </div>
        </div>
      )
    }
    return this.props.children
  }
}

/**
 * 订阅「当前会话 id」，没有就**从工作区里兜一个**。
 *
 * 为什么要兜底：`workspaceFiles` 要用会话 id，而会话属于某个工作区。
 * 在"未分组"的空会话里打开插件时 `current` 是 undefined，
 * 没有会话 id 就什么都读不了。
 */
function useSessionId(): { id: string | undefined; source: 'current' | 'fallback' | 'none' } {
  const [state, setState] = useState(() => resolveSession())
  useEffect(() => {
    const subs = [
      handles.session?.subscribe(() => setState(resolveSession())),
      handles.workspaces?.subscribe(() => setState(resolveSession())),
    ]
    return () => { for (const un of subs) un?.() }
  }, [])
  return state
}

function resolveSession(): { id: string | undefined; source: 'current' | 'fallback' | 'none' } {
  const current = handles.session?.get()
  if (current !== undefined && current !== '') return { id: current, source: 'current' }
  const items = handles.workspaces?.get()?.items ?? []
  for (const w of items) {
    const first = w.sessionIds[0]
    if (first !== undefined) return { id: first, source: 'fallback' }
  }
  return { id: undefined, source: 'none' }
}
