/**
 * 数据 hook：`工作台目录 → 版本/集 → 一集的清单+剧本 → 段落 → 批注`。
 *
 * 全部只做机械的事：读文件、解析、按规则核对行结构、把段落切出来。
 * 任何读不到 / 读不懂的地方都变成**界面上看得见的错误**，不猜、不降级。
 */

import { useCallback, useEffect, useState } from 'react'
import {
  annotationPath,
  manifestPath,
  novelPath,
  scriptPath,
  type Annotation,
  type SourceRange,
  type SourceRanges,
} from '../shared/protocol.ts'
import {
  checkScriptStructure,
  computeNovelRange,
  parseAnnotations,
  parseEpisodeManifest,
  splitLines,
  type Issue,
} from '../shared/validate.ts'
import { loadAnnotations, saveAnnotations } from './annotations.ts'
import {
  EMPTY_SCAN,
  scanWorkbench,
  tryReadText,
  type WorkbenchScan,
  type WorkspaceFilesFace,
} from './workspace.ts'

const messageOf = (error: unknown): string => (error instanceof Error ? error.message : String(error))

/**
 * 把宿主返回的批注**统一成新格式**。
 *
 * ⚠️ 为什么需要（2026-09-14 踩过）：批注格式从扁平的 `paragraph`/`quote`
 *    改成了 `regions` 数组。**宿主半边要重启服务才会更新**，所以会出现
 *    "新客户端 + 老宿主"：老宿主返回老格式，客户端直接读 `a.regions[0]`
 *    就抛异常 —— 整个工作台组件崩掉，**浮窗什么都画不出来**。
 *    这里统一过一遍 `parseAnnotations`（它本来就兼容两种格式），
 *    顺带把坏数据挡在外面，不让一条脏数据把界面搞崩。
 */
export function toAnnotations(value: unknown): Annotation[] {
  return parseAnnotations(value).annotations ?? []
}

/** 加载阶段。 */
export type Phase = 'idle' | 'loading' | 'ready' | 'error'

/* ── 工作台目录扫描 ────────────────────────────────────────────────────── */

export interface WorkbenchState {
  scan: WorkbenchScan
  phase: Phase
  error: string
  reload: () => void
}

export function useWorkbench(
  files: WorkspaceFilesFace | undefined,
  sessionId: string | undefined,
): WorkbenchState {
  const [scan, setScan] = useState<WorkbenchScan>(EMPTY_SCAN)
  const [phase, setPhase] = useState<Phase>('idle')
  const [error, setError] = useState('')
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (files === undefined || sessionId === undefined || sessionId === '') {
      setPhase('idle')
      setScan(EMPTY_SCAN)
      return
    }
    const ac = new AbortController()
    setPhase('loading')
    setError('')
    void scanWorkbench(files, sessionId, ac.signal)
      .then((result) => {
        if (ac.signal.aborted) return
        setScan(result)
        setPhase('ready')
      })
      .catch((err: unknown) => {
        if (ac.signal.aborted) return
        setError(messageOf(err))
        setPhase('error')
      })
    return () => { ac.abort() }
  }, [files, sessionId, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { scan, phase, error, reload }
}

/* ── 原文 ──────────────────────────────────────────────────────────────── */

export interface NovelState {
  lines: string[]
  phase: Phase
  error: string
}

export function useNovel(
  files: WorkspaceFilesFace | undefined,
  sessionId: string | undefined,
  enabled: boolean,
): NovelState {
  const [state, setState] = useState<NovelState>({ lines: [], phase: 'idle', error: '' })

  useEffect(() => {
    if (!enabled || files === undefined || sessionId === undefined || sessionId === '') {
      setState({ lines: [], phase: 'idle', error: '' })
      return
    }
    let alive = true
    setState({ lines: [], phase: 'loading', error: '' })
    void tryReadText(files, sessionId, novelPath())
      .then((text) => {
        if (!alive) return
        if (text === undefined) {
          setState({ lines: [], phase: 'error', error: `读不到 ${novelPath()} —— 原文还没拷进剧本工作台` })
          return
        }
        setState({ lines: splitLines(text), phase: 'ready', error: '' })
      })
      .catch((err: unknown) => {
        if (!alive) return
        setState({ lines: [], phase: 'error', error: messageOf(err) })
      })
    return () => { alive = false }
  }, [files, sessionId, enabled])

  return state
}

/* ── 一集：清单 + 剧本 → 段落 ──────────────────────────────────────────── */

/** 一个渲染用的剧本段落。 */
export interface RenderedParagraph {
  /** 段落编号（从 1 开始）—— 批注就是按它锚定的。 */
  index: number
  /** 段落文字（可能多行）。 */
  text: string
  /** 段落内的每一行。 */
  lines: string[]
  /** 在剧本文件里占的行号区间。 */
  scriptLines: SourceRange
  /** 对应原文哪几行；`null` = 新增。 */
  sourceRanges: SourceRanges | null
  /** 清单里这一段坏了（`scriptLines` 是占位）—— 画不出来，但编号要保住。 */
  broken: boolean
}

export interface EpisodeState {
  phase: Phase
  error: string
  /** 清单与剧本对不上的地方（结构校验）。 */
  issues: Issue[]
  paragraphs: RenderedParagraph[]
  /** 本集覆盖的原文范围（由所有 sourceRanges 机械取最小/最大）。 */
  novelRange: SourceRange | null
  /** 剧本文件总行数。 */
  totalLines: number
  /**
   * 重新读一次。
   *
   * ⚠️ 人工保存完**必须**调它：保存只改了磁盘，界面上的段落与行号还是旧的
   *    （旧行号去切新正文就会切错内容）。
   */
  reload: () => void
}

/** `reload` 不是"读出来的数据"，所以内部 state 用去掉它的形状。 */
type EpisodeData = Omit<EpisodeState, 'reload'>

const EMPTY_EPISODE: EpisodeData = {
  phase: 'idle', error: '', issues: [], paragraphs: [], novelRange: null, totalLines: 0,
}

/**
 * 读一集的清单 + 剧本。
 *
 * @param tag - 小版本号（如 `v2.1`）；`null` = 基线。
 *   **必须传这一集的有效版本** —— 看哪一份正文，就要配哪一份清单，
 *   两者的行号是一套；传错就会出现"清单与剧本对不上"的假报警。
 */
export function useEpisode(
  files: WorkspaceFilesFace | undefined,
  sessionId: string | undefined,
  version: string | undefined,
  episode: number | undefined,
  tag: string | null,
): EpisodeState {
  const [state, setState] = useState<EpisodeData>(EMPTY_EPISODE)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (files === undefined || sessionId === undefined || sessionId === ''
      || version === undefined || episode === undefined) {
      setState(EMPTY_EPISODE)
      return
    }
    let alive = true
    const ac = new AbortController()
    setState({ ...EMPTY_EPISODE, phase: 'loading' })

    void (async () => {
      const manifestRel = manifestPath(version, episode, tag)
      const scriptRel = scriptPath(version, episode, tag)

      const manifestText = await tryReadText(files, sessionId, manifestRel, ac.signal)
      if (manifestText === undefined) {
        if (alive) setState({ ...EMPTY_EPISODE, phase: 'error', error: `缺清单文件：${manifestRel}` })
        return
      }
      let raw: unknown
      try {
        raw = JSON.parse(manifestText)
      } catch (error) {
        if (alive) {
          setState({ ...EMPTY_EPISODE, phase: 'error', error: `${manifestRel} 不是合法 JSON：${messageOf(error)}` })
        }
        return
      }
      const parsed = parseEpisodeManifest(raw)
      if (parsed.manifest === null) {
        const detail = parsed.issues.map(i => `${i.where}：${i.message}`).join('；')
        if (alive) setState({ ...EMPTY_EPISODE, phase: 'error', error: `${manifestRel} 读不懂 —— ${detail}` })
        return
      }

      const scriptText = await tryReadText(files, sessionId, scriptRel, ac.signal)
      if (scriptText === undefined) {
        if (alive) setState({ ...EMPTY_EPISODE, phase: 'error', error: `缺剧本文件：${scriptRel}` })
        return
      }

      const lines = splitLines(scriptText)
      const paragraphs: RenderedParagraph[] = parsed.manifest.paragraphs.map((p, index) => {
        const [start, end] = p.scriptLines
        const broken = start === 0 && end === 0
        const body = broken ? [] : lines.slice(start - 1, end)
        return {
          index: index + 1,
          text: body.join('\n'),
          lines: body,
          scriptLines: p.scriptLines,
          sourceRanges: p.sourceRanges,
          broken,
        }
      })

      if (!alive) return
      setState({
        phase: 'ready',
        error: '',
        issues: [...parsed.issues, ...checkScriptStructure(scriptText, parsed.manifest)],
        paragraphs,
        novelRange: computeNovelRange(parsed.manifest),
        totalLines: lines.length,
      })
    })().catch((err: unknown) => {
      if (!alive) return
      setState({ ...EMPTY_EPISODE, phase: 'error', error: messageOf(err) })
    })

    return () => { alive = false; ac.abort() }
  }, [files, sessionId, version, episode, tag, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { ...state, reload }
}

/* ── 批注 ──────────────────────────────────────────────────────────────── */

export interface AnnotationsState {
  phase: Phase
  error: string
  annotations: Annotation[]
  /** 保存中（禁用按钮用）。 */
  saving: boolean
  /** 重新从磁盘读。 */
  reload: () => void
  /** 保存整个列表；成功返回 true。 */
  save: (next: readonly Annotation[]) => Promise<boolean>
}

export function useAnnotations(
  sessionId: string | undefined,
  version: string | undefined,
  episode: number | undefined,
  tag: string | null,
): AnnotationsState {
  const [phase, setPhase] = useState<Phase>('idle')
  const [error, setError] = useState('')
  const [annotations, setAnnotations] = useState<Annotation[]>([])
  const [saving, setSaving] = useState(false)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (sessionId === undefined || sessionId === '' || version === undefined || episode === undefined) {
      setPhase('idle')
      setAnnotations([])
      return
    }
    let alive = true
    setPhase('loading')
    setError('')
    void loadAnnotations(sessionId, version, episode, tag)
      .then((result) => {
        if (!alive) return
        if (!result.ok) {
          setAnnotations([])
          setError(result.error)
          setPhase('error')
          return
        }
        setAnnotations(toAnnotations(result.annotations))
        setPhase('ready')
      })
      .catch((err: unknown) => {
        if (!alive) return
        setError(messageOf(err))
        setPhase('error')
      })
    return () => { alive = false }
  }, [sessionId, version, episode, tag, nonce])

  const save = useCallback(async (next: readonly Annotation[]): Promise<boolean> => {
    if (sessionId === undefined || sessionId === '' || version === undefined || episode === undefined) {
      setError('还没有可用的会话 / 集，存不了批注')
      return false
    }
    setSaving(true)
    try {
      const result = await saveAnnotations(sessionId, version, episode, tag, next)
      if (!result.ok) {
        setError(result.error)
        return false
      }
      setAnnotations(result.annotations)
      setError('')
      setPhase('ready')
      return true
    } catch (err: unknown) {
      setError(messageOf(err))
      return false
    } finally {
      setSaving(false)
    }
  }, [sessionId, version, episode, tag])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { phase, error, annotations, saving, reload, save }
}

/** 批注文件的路径（界面上显示"存到哪儿"用）。 */
export const annotationsPathOf = annotationPath
