/**
 * 数据层：从**固定目录**读工作台，读原文 / 剧本 / 清单。
 *
 * 与旧版的区别（设计文档 §9.2）：这里是"读固定目录 + 按文件名配对"，
 * **不再扫描整个工作区、不再猜哪个文件是什么**。
 *
 * 一条实测出来的契约：`workspaceFiles.list/read` 的**第一个参数是会话 id**，
 * 不是工作区 id —— 会话锚定了工作区根，所以"读哪个工作区"由当前会话决定。
 *
 * ⚠️ 从人工编辑模式起，一个大版本目录里除了基线文件还会有**小版本文件**
 *    （`第1集剧本.v2.1.txt`）。"哪堆文件属于哪一集、哪一版有效"这段判断
 *    全部在 `shared/versions.ts` 的 `groupVersion` 里（纯函数、有回归用例），
 *    这里只负责把目录列出来喂给它。
 */

import {
  ANNOTATION_DIR,
  CHANGELOG_FILE,
  HISTORY_DIR,
  MANIFEST_DIR,
  NOVEL_FILE,
  SCRIPT_DIR,
  WORKBENCH_DIR,
  compareVersions,
  versionOfDir,
} from '../shared/protocol.ts'
import { groupVersion, type VersionEntry } from '../shared/versions.ts'

/** 官方 `workspaceFiles` Remote 里我们用到的两个方法（最小面）。 */
export interface WorkspaceFilesFace {
  list(
    sessionId: string,
    path: string,
    signal?: AbortSignal,
  ): Promise<RemoteResult<{
    path: string
    entries: ReadonlyArray<{ name: string; type: 'file' | 'directory' | 'other'; size?: number }>
    truncated: boolean
  }>>
  read(
    sessionId: string,
    path: string,
    range: { offset?: number; limit?: number },
    signal?: AbortSignal,
  ): Promise<RemoteResult<{ text: string; lines: number; offset: number; eof: boolean; absolutePath: string }>>
}

/** 官方 Remote 的返回信封。 */
export type RemoteResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: { readonly code: string; readonly message: string } }

/** 单次读取最多翻多少页（一页默认 5000 行）。 */
const MAX_READ_PAGES = 40

/** 读一页。 */
async function readPage(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  offset: number,
  signal?: AbortSignal,
): Promise<{ text: string; lines: number; eof: boolean }> {
  const result = await files.read(sessionId, path, { offset }, signal)
  if (!result.ok) throw new Error(`读不了 ${path}：${result.error.code} ${result.error.message}`)
  return { text: result.value.text, lines: result.value.lines, eof: result.value.eof }
}

/**
 * 读一整份文本（**自动翻页**）。
 *
 * ⚠️ `read` 一次只给一页（默认 5000 行），超出只回 `eof:false`，**不报错也不提示** ——
 *    合集文件很容易超，静默截断会让人看到"看起来完整"的半份稿子。
 *    分页语义：页间用 `\n` 拼接即可精确还原，行号与物理行号一致。
 */
export async function readText(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<string> {
  const first = await readPage(files, sessionId, path, 1, signal)
  let text = first.text
  let cursor = 1 + first.lines
  let done = first.eof
  let pages = 1
  while (!done && pages < MAX_READ_PAGES) {
    if (signal?.aborted) break
    const page = await readPage(files, sessionId, path, cursor, signal)
    if (page.lines === 0) break
    text += `\n${page.text}`
    cursor += page.lines
    done = page.eof
    pages += 1
  }
  return text
}

/** 读文本；**不存在**时返回 `undefined`（其它错误照抛）。 */
export async function tryReadText(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<string | undefined> {
  try {
    return await readText(files, sessionId, path, signal)
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    if (/not-found|no entry|不存在|FS_NOT_FOUND/i.test(text)) return undefined
    throw error
  }
}

/** 一个目录里有什么。`undefined` = 目录不存在（其它错误照抛）。 */
export interface DirListing {
  dirs: string[]
  files: string[]
}

export async function listDir(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<DirListing | undefined> {
  let result: Awaited<ReturnType<WorkspaceFilesFace['list']>>
  try {
    result = await files.list(sessionId, path, signal)
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    if (/not-found|no entry|不存在|FS_NOT_FOUND/i.test(text)) return undefined
    throw error
  }
  if (!result.ok) {
    if (/not-found|no entry|FS_NOT_FOUND/i.test(`${result.error.code} ${result.error.message}`)) return undefined
    throw new Error(`读不了目录 ${path}：${result.error.code} ${result.error.message}`)
  }
  const dirs: string[] = []
  const fileNames: string[] = []
  for (const entry of result.value.entries) {
    if (entry.type === 'directory') dirs.push(entry.name)
    else if (entry.type === 'file') fileNames.push(entry.name)
  }
  return { dirs, files: fileNames }
}

/* ── 扫描工作台 ────────────────────────────────────────────────────────── */

/** 扫描结果。 */
export interface WorkbenchScan {
  /** `missing` = 工作区里没有 `剧本工作台/`；`ready` = 有，且读到了版本信息。 */
  phase: 'missing' | 'ready' | 'empty' | 'error'
  /** 有没有 `小说原文.txt`。 */
  hasNovel: boolean
  versions: VersionEntry[]
  /** 机械体检出来的问题（缺文件、重号、文件名不认识、哪一版不完整…）。 */
  issues: string[]
  error: string
}

const EMPTY_SCAN: WorkbenchScan = {
  phase: 'error', hasNovel: false, versions: [], issues: [], error: '还没有开始扫描',
}

/** 版本目录里我们关心的四个子目录 —— 顺序固定，方便日志与用例。 */
const SUB_DIRS: readonly string[] = [SCRIPT_DIR, MANIFEST_DIR, ANNOTATION_DIR, HISTORY_DIR]

/**
 * 扫 `剧本工作台/`：有哪些版本、每个版本有哪些集、每集哪一版有效。
 *
 * 只做机械检查（文件在不在、名字认不认识），**不判断剧情内容**；
 * "哪一版有效"由 `groupVersion` 判定（正文 + 清单都齐的最高小版本）。
 */
export async function scanWorkbench(
  files: WorkspaceFilesFace,
  sessionId: string,
  signal?: AbortSignal,
): Promise<WorkbenchScan> {
  const root = await listDir(files, sessionId, '.', signal)
  if (root === undefined || !root.dirs.includes(WORKBENCH_DIR)) {
    return { phase: 'missing', hasNovel: false, versions: [], issues: [], error: '' }
  }

  const issues: string[] = []
  const bench = await listDir(files, sessionId, WORKBENCH_DIR, signal)
  if (bench === undefined) {
    return { phase: 'error', hasNovel: false, versions: [], issues: [], error: `读不了 ${WORKBENCH_DIR}/` }
  }
  const hasNovel = bench.files.includes(NOVEL_FILE)
  if (!hasNovel) issues.push(`缺 ${NOVEL_FILE} —— 原文还没拷进剧本工作台`)

  const versionDirs = bench.dirs
    .map(dir => ({ dir, version: versionOfDir(dir) }))
    .filter((x): x is { dir: string; version: string } => x.version !== undefined)
    .sort((a, b) => compareVersions(a.version, b.version))

  if (versionDirs.length === 0) {
    return { phase: 'empty', hasNovel, versions: [], issues, error: '' }
  }

  const versions: VersionEntry[] = []
  for (const { dir } of versionDirs) {
    const inside = await listDir(files, sessionId, `${WORKBENCH_DIR}/${dir}`, signal)
    const listed: Record<string, readonly string[]> = {}
    for (const sub of SUB_DIRS) {
      if (inside === undefined || !inside.dirs.includes(sub)) {
        listed[sub] = []
        continue
      }
      const dirListing = await listDir(files, sessionId, `${WORKBENCH_DIR}/${dir}/${sub}`, signal)
      listed[sub] = dirListing?.files ?? []
    }
    const grouped = groupVersion({
      dir,
      word: SCRIPT_DIR,
      files: listed,
      hasChangelog: inside?.files.includes(CHANGELOG_FILE) === true,
    })
    /* 问题都带上"哪个版本目录"，界面上才指得清。 */
    for (const issue of grouped.issues) issues.push(`${dir} ${issue}`)
    for (const entry of grouped.episodes) {
      for (const issue of entry.issues) issues.push(`${dir} ${issue}`)
    }
    versions.push(grouped)
  }

  return { phase: 'ready', hasNovel, versions, issues, error: '' }
}

export { EMPTY_SCAN }
