/**
 * 批注通道的浏览器端：把界面上的批注存/取回宿主。
 *
 * 通道是官方 `/api` 载体上的一个 exact Fetch route（自带 Host/Origin 校验与
 * 浏览器认证）。路径与请求体形状见 `shared/protocol.ts`。
 *
 * 设计文档 §17 说明：**读盘、按 id 合并、写盘都在宿主侧一次完成**，
 * 浏览器只负责把当前列表送过去；同时"文件不存在才当空数组、损坏就停止保存"
 * 也由宿主判断，这里只把错误原文带回界面。
 *
 * ⚠️ 人工编辑模式之后多了一个 `minor`：批注跟着**有效版本**走 ——
 *    界面上看的是 `第1集剧本.v2.2.txt`，批注就要存在 `第1集批注.v2.2.txt`；
 *    两边不一致会出现"看到的是 v2.2 的批注、写进 v2.1 的文件"。
 */

import {
  ANNOTATION_ROUTE,
  type Annotation,
  type AnnotationRequest,
  type AnnotationResponse,
} from '../shared/protocol.ts'

/** 调用批注通道。 */
export async function callAnnotations(
  body: AnnotationRequest,
  signal?: AbortSignal,
): Promise<AnnotationResponse> {
  let response: Response
  try {
    response = await fetch(ANNOTATION_ROUTE, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
      ...(signal === undefined ? {} : { signal }),
    })
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    return { ok: false, error: `连不上批注通道（${ANNOTATION_ROUTE}）：${text}` }
  }
  if (!response.ok) {
    return { ok: false, error: `批注通道返回 HTTP ${response.status}` }
  }
  try {
    return (await response.json()) as AnnotationResponse
  } catch {
    return { ok: false, error: '批注通道返回的不是合法 JSON' }
  }
}

/** 请求体里的小版本字段：`null` 就不带这个字段（= 基线）。 */
function minorField(minor: string | null | undefined): { minor?: string } {
  return minor === null || minor === undefined || minor === '' ? {} : { minor }
}

/** 读一集的批注。 */
export function loadAnnotations(
  sessionId: string,
  version: string,
  episode: number,
  minor: string | null | undefined,
  signal?: AbortSignal,
): Promise<AnnotationResponse> {
  return callAnnotations({ op: 'load', sessionId, version, episode, ...minorField(minor) }, signal)
}

/** 存一集的批注（返回宿主合并后的结果）。 */
export function saveAnnotations(
  sessionId: string,
  version: string,
  episode: number,
  minor: string | null | undefined,
  annotations: readonly Annotation[],
): Promise<AnnotationResponse> {
  return callAnnotations({
    op: 'save', sessionId, version, episode, ...minorField(minor), annotations: [...annotations],
  })
}
