/**
 * 保存通道的浏览器端：把"改完的全文 + 编辑过程中的快照"交给宿主。
 *
 * 通道是官方 `/api` 载体上的一个 exact Fetch route（路径见 `shared/protocol.ts`
 * 的 `EDIT_ROUTE`）。**读盘比对、按内容对齐、写新小版本的三件套、写历史**
 * 全部在宿主侧一次完成，这里只把结果带回界面。
 *
 * ⚠️ 这条通道**只新增文件**，永远不会覆盖老版本；失败时宿主会明确说
 *    "已经写了哪几个文件"，界面照原话显示，不假装成功。
 */

import { EDIT_ROUTE, type EditRequest, type EditResponse } from '../shared/protocol.ts'

/** 提交一次人工编辑。 */
export async function submitEdit(body: EditRequest, signal?: AbortSignal): Promise<EditResponse> {
  let response: Response
  try {
    response = await fetch(EDIT_ROUTE, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
      ...(signal === undefined ? {} : { signal }),
    })
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    return { ok: false, error: `连不上保存通道（${EDIT_ROUTE}）：${text}` }
  }
  if (!response.ok) {
    return { ok: false, error: `保存通道返回 HTTP ${response.status}` }
  }
  try {
    return (await response.json()) as EditResponse
  } catch {
    return { ok: false, error: '保存通道返回的不是合法 JSON' }
  }
}
