/**
 * 剧本批注工作台（设计文档 `docs/执行设计-v2.md`）。
 *
 * 三栏：小说原文 / 第 N 集剧本 / 批注。
 *
 * 这一版**不判断剧情内容**：剧本按"剧本段落"渲染，段落是角色、对白、动作还是转场，
 * 程序一概不管；对应关系完全照清单里的 `sourceRanges` 用。
 *
 * 交互：
 *   · 悬停/点击剧本段落 → 左侧原文高亮这一段对应的原文行；
 *   · 在段落里划词 → 右侧批注栏出现"写问题"的框（一次只能选一段内的连续文字）；
 *   · 点批注卡上的「定位」→ 跳到那一段；
 *   · 清单与剧本对不上 / 文件缺失 → 顶部醒目地说出来，不猜。
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type MouseEvent,
  type ReactNode,
} from 'react'
import type { Annotation, AnnotationRegion } from '../shared/protocol.ts'
import { novelPath } from '../shared/protocol.ts'
import {
  buildInstruction as renderInstruction,
  regionLabel,
  type InstructionEpisode,
} from '../shared/instruction.ts'
import { makeAnnotation, nextAnnotationSeq, type Issue } from '../shared/validate.ts'
import { toAnnotations, useAnnotations, useEpisode, useNovel, useWorkbench } from './data.ts'
import { effectiveLabel, type EpisodeEntry } from '../shared/versions.ts'
import { loadAnnotations, saveAnnotations } from './annotations.ts'
import { submitEdit } from './edit.ts'
import { setUnsaved } from './unsaved.ts'
import {
  containsQuote,
  deriveParagraphs,
  initialSnapshotState,
  snapshotReducer,
  snapshotsForSubmit,
  type DerivedParagraph,
  type SnapshotState,
} from '../shared/edit.ts'
import type { RenderedParagraph } from './data.ts'
import { useWorkbenchGeometry } from './geometry.ts'
import type { WorkspaceFilesFace } from './workspace.ts'

/** 编辑模式里一集的草稿（每集各留一份，来回切集不丢）。 */
interface DraftState {
  /** 当前正文（就是文本框里的值）。 */
  text: string
  /** 进入编辑时那一版的正文（冲突检测与"改没改"都跟它比）。 */
  baseText: string
  /** 基线那一版的小版本号（如 `v1.1`）；基线本身是 `null`。 */
  baseMinor: string | null
  /** 快照状态机（停手拍帧；中文输入法组合期间不拍）。 */
  snap: SnapshotState
}

/** 毫秒 → `14:20:44`（历史/提示里给人看的时间）。 */
function clockOf(ms: number): string {
  return new Date(ms).toTimeString().slice(0, 8)
}

/** 光标偏移 → 第几行（1 基）。 */
function lineOfOffset(text: string, offset: number): number {
  const clamped = Math.max(0, Math.min(offset, text.length))
  return text.slice(0, clamped).split('\n').length
}

/** 列宽约束：两侧最小 180，中间至少留 260。 */
const MIN_SIDE = 180
const MIN_MID = 260

/** 浮动批注框的尺寸（用来把它夹进视口，免得贴边被切）。 */
const POPUP_W = 320
const POPUP_H = 210

/** 一处区域的显示名：`第 6 段` / `第 3–7 段`（实现挪到 `shared/instruction.ts`，那里有用例）。 */

/** 把几处区域摊平成段落号（去重、升序）—— 高亮和跳转都用它。 */
function paragraphsOfRegions(regions: readonly AnnotationRegion[]): number[] {
  const out = new Set<number>()
  for (const region of regions) {
    const to = region.endParagraph ?? region.paragraph
    for (let index = region.paragraph; index <= to; index += 1) out.add(index)
  }
  return [...out].sort((a, b) => a - b)
}

/**
 * 未登记时给主人复制的那句话。
 *
 * 写得具体是因为 agent 需要知道**完整流程**：建目录、准备原文、一集一集调工具、
 * 先跑第 1 集。
 *
 * ⚠️ 第 2 步分两种情形（2026-09-15 加的）：原文是**整份拷**还是**按这一季的剧本
 *    节选一段**。为什么允许节选：原文动辄几十万字，整份放进工作台会让原文栏
 *    要渲染几万个 DOM 节点（还有工具每次都要把整份读一遍数行数），卡得没法用。
 *    但节选有一个硬前提：**范围要覆盖这一季的全部集数**，否则后面几集登记时
 *    原文里没有对应行，会静默变成"新增"、界面上只是高亮不出来，不报错。
 *    所以要求 agent **先报范围、等用户确认**再拷。
 */
const REGISTER_PROMPT = [
  '请把这个工作区建成「剧本批注工作台」。步骤：',
  '',
  '1. 在工作区根目录下建 `剧本工作台/` 文件夹。',
  '2. 把小说原文**准备**成 `剧本工作台/小说原文.txt`：',
  '   · **原文不长**（比如几千行以内）：直接整份拷过来（用 Copy-Item，字节复制，',
  '     不要用 Get-Content/Set-Content）。用户原始的稿子一个字都不要动。',
  '   · **原文很长**：不要整份拷，**按章截**（长篇小说都是按章走的）：',
  '     先判断我给你的这份剧本（一季）覆盖原文的哪几章（例如"第 12 章—第 20 章"），',
  '     然后**从第 12 章的开头截到第 20 章的结尾**（整章保留，不要切在半章中间），',
  '     再拷进 `小说原文.txt`。',
  '     拷之前**把章的范围和依据报给我、等我确认**；原文没有分章标记、或者判断不出',
  '     边界，就**直接问我**，不要猜、也不要先拷一整份。',
  '   · 节选之后，原文行号**从 1 重新算**：后面登记的 sourceRanges 都以节选后的',
  '     行号为准。以后要做这一季之外的集，得按同样的办法扩范围（也按章扩），',
  '     并把受影响集数的 sourceRanges 跟着重算。',
  '3. 逐集登记：把剧本正文按"段落"切开，每段判断它来自原文哪几行，',
  '   然后用 novel_script_write_episode 工具提交（一次一集）。',
  '   · 段落 = 可独立高亮和批注的一段文字，内部可以多行，但**不能有空白行**；',
  '   · 原文里没有对应的段落，sourceRanges 写 null（比如 FADE IN:、场景标题、新增动作）；',
  '   · 只保留纯剧情正文，去掉来源依据、附录、表格、SOURCE_BLOCK 标记、章节标记。',
  '4. **先只做第 1 集**，让我在工作台看一眼，确认没问题再继续第 2 集，然后才是剩下的。',
  '',
  '注意：不要自己手写剧本文件和清单文件 —— 行号、段落编号、文件生成都由工具负责。',
].join('\n')

export function Workbench({
  files,
  sessionId,
  sessionSource,
}: {
  files?: WorkspaceFilesFace
  sessionId?: string
  sessionSource?: 'current' | 'fallback' | 'none'
}): ReactNode {
  const wb = useWorkbench(files, sessionId)
  const scan = wb.scan

  /* ── 选哪一版、哪一集 ─────────────────────────────────────────────────
     默认打开**最新的一版**（审阅就是看最新的）和它的第 1 集。 */
  const [pickVersion, setPickVersion] = useState<string | null>(null)
  const [pickEpisode, setPickEpisode] = useState<number | null>(null)

  const version = useMemo(() => {
    const list = scan.versions
    if (list.length === 0) return null
    return list.find(v => v.version === pickVersion) ?? list[list.length - 1] ?? null
  }, [scan.versions, pickVersion])

  const episode = useMemo(() => {
    const list = version?.episodes ?? []
    if (list.length === 0) return null
    return list.find(e => e.episode === pickEpisode) ?? list[0] ?? null
  }, [version, pickEpisode])

  /** 上一集 / 下一集（主人要的两个按钮）。 */
  const episodeNav = useMemo(() => {
    const list = version?.episodes ?? []
    const index = episode === null ? -1 : list.findIndex(e => e.episode === episode.episode)
    return {
      prev: index > 0 ? list[index - 1] : undefined,
      next: index >= 0 && index < list.length - 1 ? list[index + 1] : undefined,
    }
  }, [version, episode])

  /* ⚠️ 传给数据 hook 的是**版本目录名**（`v1`），不是去掉 v 的版本号（`1`）：
     拼路径的函数按 `剧本工作台/<目录名>/…` 拼。混淆过一次，
     表现是"清单文件找不到：剧本工作台/1/清单/…"，剧本栏整个空白。 */
  /* 这一集当前该看 / 该改的那一版：有效版本是小版本（如 v2.2）时，
     正文、清单、批注都读那一份；没有小版本就是基线。 */
  const effTag = episode?.effective.tag ?? null

  const ep = useEpisode(files, sessionId, version?.dir, episode?.episode, effTag)
  const novel = useNovel(files, sessionId, scan.phase === 'ready' || scan.phase === 'empty')
  const anno = useAnnotations(sessionId, version?.dir, episode?.episode, effTag)

  /* ── 人工编辑模式（实施计划 §7）─────────────────────────────────────────
     规矩：
       · 只有**最新大版本**、而且清单与正文对得上时才允许编辑；
       · 编辑期间划词批注与"钉住高亮"暂停（点一下就是放光标）；
       · **没有自动保存**：只有点「保存」才写盘（写成新小版本），「放弃」什么都不写；
       · 每集各留一份草稿；切集 / 切版本 / 关窗口时有未保存改动会先问一句。 */
  const [editMode, setEditMode] = useState(false)
  const [drafts, setDrafts] = useState<Record<string, DraftState>>({})
  const [savingDraft, setSavingDraft] = useState(false)
  const [caretLine, setCaretLine] = useState(1)
  const taRef = useRef<HTMLTextAreaElement | null>(null)
  const gutRef = useRef<HTMLDivElement | null>(null)

  const latestVersionDir = scan.versions[scan.versions.length - 1]?.dir ?? null
  const structureOk = ep.phase === 'ready' && !ep.issues.some(issue => issue.level === 'error')
  const canEdit = version !== null && version.dir === latestVersionDir && structureOk
  const draftKey = `${version?.dir ?? ''}#${episode?.episode ?? 0}`

  /**
   * 该集"这一版的正文"。
   *
   * 为什么是"把清单切出来的段落拼回去"：正文文件本来就是"段落之间一个空白行"
   * 拼成的（`buildScriptText`），所以拼回去 == 文件本身。一旦清单与正文对不上
   * （`ep.issues` 里有 error），拼回去可能丢内容 —— 那种情况**不允许编辑**。
   */
  const baseDraft = useMemo<DraftState | null>(() => {
    if (ep.phase !== 'ready' || !structureOk) return null
    const text = ep.paragraphs.map(p => p.text).join('\n\n')
    return { text, baseText: text, baseMinor: effTag, snap: initialSnapshotState(text) }
  }, [ep, effTag, structureOk])

  const draft = drafts[draftKey] ?? baseDraft
  const draftDirty = draft !== null && draft.text !== draft.baseText

  /** 编辑面上每一行的行号（**编辑模式下左边只显示行号**，不显示段号）。 */
  const draftLines = useMemo(() => (draft === null ? [] : draft.text.split('\n')), [draft])

  /** 改草稿的唯一入口（顺带把快照状态机推进一步）。 */
  const mutateDraft = useCallback((updater: (cur: DraftState) => DraftState): void => {
    setDrafts((prev) => {
      const cur = prev[draftKey] ?? baseDraft
      if (cur === null) return prev
      return { ...prev, [draftKey]: updater(cur) }
    })
  }, [draftKey, baseDraft])

  /**
   * 光标移动 → 记下在第几行（底栏据此显示"光标所在段 → 原文哪几行"）。
   *
   * ⚠️ 从 ref 上取值，**不要用事件对象**：React 在事件派发结束后会把合成事件的
   *    `currentTarget` 置成 null，而这个回调可能稍后才跑（见 textarea 上的注释，
   *    2026-09-15 因此在输入法组合期间崩过一次）。
   */
  const updateCaretFromRef = useCallback((): void => {
    const ta = taRef.current
    if (ta === null) return
    setCaretLine(lineOfOffset(ta.value, ta.selectionStart))
  }, [])

  /**
   * 编辑期间的"对照预览"（纯机械算一遍，不落盘）：
   * 拿当前草稿跟这一版的正文按内容对齐，就知道**光标所在那一段**对应原文哪几行。
   * 段号与对应关系只有保存后才写进新清单；这里只是让改的时候有个参照。
   *
   * ⚠️ 用**停手 250ms 后的那份文本**算（`previewText`）：每敲一个字都重算一遍
   *    对齐没必要，还会让打字手感变钝。行号槽不受影响 —— 那个只是数行数。
   */
  const [previewText, setPreviewText] = useState<string | null>(null)
  useEffect(() => {
    if (!editMode || draft === null) { setPreviewText(null); return }
    const timer = window.setTimeout(() => setPreviewText(draft.text), 250)
    return () => { window.clearTimeout(timer) }
  }, [editMode, draft])

  const livePreview = useMemo(() => {
    if (!editMode || previewText === null || ep.phase !== 'ready' || !structureOk) return null
    const oldLines = ep.paragraphs.flatMap((p, index) => (index === 0 ? p.lines : ['', ...p.lines]))
    return deriveParagraphs(
      oldLines,
      previewText.split('\n'),
      ep.paragraphs.map(p => ({ scriptLines: p.scriptLines, sourceRanges: p.sourceRanges })),
    )
  }, [editMode, previewText, ep, structureOk])

  /** 光标所在那一段（光标落在两段之间时取前面最近的一段）。 */
  const caretParagraph = useMemo<DerivedParagraph | null>(() => {
    if (livePreview === null) return null
    const inside = livePreview.paragraphs.find(p => caretLine >= p.span.start && caretLine <= p.span.end)
    if (inside !== undefined) return inside
    let before: DerivedParagraph | null = null
    for (const p of livePreview.paragraphs) if (p.span.start <= caretLine) before = p
    return before
  }, [livePreview, caretLine])

  /** "有没有没保存的改动"要告诉外面：关浮层的按钮在另一个模块里。 */
  const anyDirty = useMemo(() => Object.values(drafts).some(d => d.text !== d.baseText), [drafts])
  useEffect(() => {
    setUnsaved(editMode && anyDirty)
    return () => { setUnsaved(false) }
  }, [editMode, anyDirty])

  /** 刷新 / 关标签页也拦一下。 */
  useEffect(() => {
    if (!editMode || !anyDirty) return
    const onUnload = (e: BeforeUnloadEvent): void => { e.preventDefault(); e.returnValue = '' }
    window.addEventListener('beforeunload', onUnload)
    return () => { window.removeEventListener('beforeunload', onUnload) }
  }, [editMode, anyDirty])

  /** 每秒推进一次快照状态机（停手 3 秒拍一张；组合期间它自己不拍）。 */
  useEffect(() => {
    if (!editMode) return
    const timer = window.setInterval(() => {
      const now = Date.now()
      setDrafts((prev) => {
        const cur = prev[draftKey]
        if (cur === undefined) return prev
        const next = snapshotReducer(cur.snap, { kind: 'tick', at: clockOf(now), nowMs: now })
        if (next === cur.snap) return prev
        return { ...prev, [draftKey]: { ...cur, snap: next } }
      })
    }, 1000)
    return () => { window.clearInterval(timer) }
  }, [editMode, draftKey])

  /** 切走之前先问一句（有未保存改动时）。 */
  const leaveGuard = useCallback((): boolean => {
    if (!draftDirty) return true
    return window.confirm('这一集还有没保存的人工改动，切走就丢了。确定切走吗？')
  }, [draftDirty])

  const pickEpisodeGuarded = useCallback((episodeNo: number): void => {
    if (leaveGuard()) setPickEpisode(episodeNo)
  }, [leaveGuard])

  const pickVersionGuarded = useCallback((dir: string): void => {
    if (!leaveGuard()) return
    setEditMode(false)
    setPickVersion(dir)
    setPickEpisode(null)
  }, [leaveGuard])

  /* ── 批注栏：按集看 / 全部看 ────────────────────────────────────────────
     批注是**按集一个文件**存的，所以"全部"要把这一版每一集的批注都读回来
     （一集一次请求，并行发；本地很快）。只有真的切到"全部"才去读，
     免得每次打开工作台都打 46 个请求。 */
  const [annoScope, setAnnoScope] = useState<'episode' | 'all'>('episode')
  const [allAnnotations, setAllAnnotations] = useState<Record<number, Annotation[]>>({})
  const [allError, setAllError] = useState('')
  const [allNonce, setAllNonce] = useState(0)

  useEffect(() => {
    if (annoScope !== 'all' || sessionId === undefined || sessionId === '' || version == null) return
    const dir = version.dir
    const list = version.episodes
    if (list.length === 0) return
    let alive = true
    setAllError('')
    void Promise.all(list.map(async (item) => {
      const result = await loadAnnotations(sessionId, dir, item.episode, item.effective.tag)
      return [item.episode, result] as const
    })).then((pairs) => {
      if (!alive) return
      const next: Record<number, Annotation[]> = {}
      const errors: string[] = []
      for (const [episodeNo, result] of pairs) {
        if (result.ok) next[episodeNo] = toAnnotations(result.annotations)
        else errors.push(`第 ${episodeNo} 集：${result.error}`)
      }
      setAllAnnotations(next)
      if (errors.length > 0) setAllError(errors.join('；'))
    }).catch((err: unknown) => {
      if (alive) setAllError(err instanceof Error ? err.message : String(err))
    })
    return () => { alive = false }
  }, [annoScope, sessionId, version, allNonce])

  /** "全部"模式下总共多少条。 */
  const allCount = useMemo(
    () => Object.values(allAnnotations).reduce((n, list) => n + list.length, 0),
    [allAnnotations],
  )

  /* ── 高亮：悬停 / 钉住某几段 → 它们在原文里对应的行 ───────────────────
     钉住的是**一组段落号**（可以是不连续的几个 —— Ctrl 多选的结果）。 */
  const [hoverParagraph, setHoverParagraph] = useState<number | null>(null)
  const [pinnedParagraphs, setPinnedParagraphs] = useState<number[]>([])

  const isPinned = useCallback(
    (index: number): boolean => pinnedParagraphs.includes(index),
    [pinnedParagraphs],
  )

  /** 当前要高亮的段落：钉住优先，否则看悬停的那一段。 */
  const activeParagraphs = useMemo<RenderedParagraph[]>(() => {
    if (pinnedParagraphs.length > 0) {
      return ep.paragraphs.filter(p => pinnedParagraphs.includes(p.index))
    }
    if (hoverParagraph === null) return []
    return ep.paragraphs.filter(p => p.index === hoverParagraph)
  }, [ep.paragraphs, pinnedParagraphs, hoverParagraph])

  /** 当前要高亮的原文行（钉住多段时取并集；**编辑模式下跟着光标走**）。 */
  const highlightLines = useMemo(() => {
    const out = new Set<number>()
    if (editMode && caretParagraph !== null) {
      for (const [a, b] of caretParagraph.sourceRanges ?? []) {
        for (let ln = a; ln <= b; ln += 1) out.add(ln)
      }
      return out
    }
    for (const paragraph of activeParagraphs) {
      for (const [a, b] of paragraph.sourceRanges ?? []) {
        for (let ln = a; ln <= b; ln += 1) out.add(ln)
      }
    }
    return out
  }, [activeParagraphs, editMode, caretParagraph])

  /**
   * 本集覆盖范围那根**竖条**的位置。
   *
   * 主人 2026-09-14：整集覆盖要用**一根连续的竖条**表示。
   * 如果按"每行一道 inset 阴影"来画，行的圆角 + 行距会把它切成一截截
   * （看起来像一串括号）。所以这里量出第一条与最后一条被覆盖的行，
   * 单独画一根绝对定位的竖条。
   */
  const [coverBar, setCoverBar] = useState<{ top: number; height: number } | null>(null)

  useEffect(() => {
    const box = novelRef.current
    const range = ep.novelRange
    if (box === null || range === null || novel.phase !== 'ready') {
      setCoverBar(null)
      return
    }
    const first = box.querySelector<HTMLElement>(`[data-ln="${range[0]}"]`)
    const last = box.querySelector<HTMLElement>(`[data-ln="${range[1]}"]`)
    if (first === null || last === null) {
      setCoverBar(null)
      return
    }
    setCoverBar({ top: first.offsetTop, height: last.offsetTop + last.offsetHeight - first.offsetTop })
  }, [ep.novelRange, novel.phase, novel.lines.length])

  /* ── 划词 → 待写的批注 ──────────────────────────────────────────────── */
  const scriptRef = useRef<HTMLDivElement | null>(null)
  const novelRef = useRef<HTMLDivElement | null>(null)
  /** 批注框（跟着选区浮出来的那个）的 DOM，用来判断"点框外"。 */
  const popRef = useRef<HTMLDivElement | null>(null)
  /** 待写的批注：已经选了哪几处（Ctrl 累积）、批注框浮在哪儿、框是否已经弹出来。 */
  const [pending, setPending] = useState<{
    regions: AnnotationRegion[]
    x: number
    y: number
    /** false = 还按着 Ctrl 在连选：只显示一条"已选 N 处"的提示，**不弹输入框**。 */
    open: boolean
  } | null>(null)
  const [problem, setProblem] = useState('')
  const [toast, setToast] = useState('')

  /* ── 编辑模式的三个动作（放在 toast 之后：保存失败要把宿主的话显示出来）── */

  /** 开/关编辑模式。退出时若有未保存改动先问一句。 */
  const toggleEditMode = useCallback((): void => {
    if (editMode) {
      if (draftDirty && !window.confirm('还有没保存的改动，退出编辑就丢了。确定退出吗？')) return
      setEditMode(false)
      return
    }
    if (!canEdit) return
    setEditMode(true)
    setCaretLine(1)
  }, [editMode, draftDirty, canEdit])

  /** 放弃这次改动（什么都不写）。 */
  const discardDraft = useCallback((): void => {
    if (!draftDirty) return
    if (!window.confirm('放弃这次改动？改的内容不会写进任何文件。')) return
    setDrafts((prev) => {
      const next = { ...prev }
      delete next[draftKey]
      return next
    })
  }, [draftDirty, draftKey])

  /**
   * 保存：交给宿主写成**新小版本**（正文 + 清单 + 批注 + 历史）。
   *
   * ⚠️ 失败时**草稿原样留着**，把宿主的话原样显示出来 —— 不假装保存成功，
   *    也不因为失败就把用户改的内容丢掉。
   */
  const saveDraft = useCallback(async (): Promise<void> => {
    if (draft === null || version === null || episode === null) return
    if (sessionId === undefined || sessionId === '') { setToast('还没有可用的会话，存不了'); return }
    const now = Date.now()
    const snap = snapshotReducer(draft.snap, { kind: 'flush', text: draft.text, at: clockOf(now), nowMs: now })
    const submitted = snapshotsForSubmit(snap)
    setSavingDraft(true)
    const result = await submitEdit({
      sessionId,
      version: version.dir,
      episode: episode.episode,
      baseMinor: draft.baseMinor,
      baseText: draft.baseText,
      text: draft.text,
      snapshots: submitted.frames,
    })
    setSavingDraft(false)
    if (!result.ok) {
      mutateDraft(cur => ({ ...cur, snap }))
      setToast(`没保存成功：${result.error}`)
      return
    }
    setToast(
      `已保存为 ${result.minor}（+${result.summary.added} 行 / -${result.summary.removed} 行；`
      + `清单已同步${result.annotations.stale.length === 0 ? '' : `，${result.annotations.stale.length} 条批注锚点失效`}）`,
    )
    /* 这一版已经落盘，草稿作废；重新读之后有效版本就变成新的小版本了。 */
    setDrafts((prev) => {
      const next = { ...prev }
      delete next[draftKey]
      return next
    })
    wb.reload()
    ep.reload()
    anno.reload()
  }, [draft, version, episode, sessionId, mutateDraft, draftKey, wb, ep, anno])

  useEffect(() => {
    if (toast === '') return
    const timer = window.setTimeout(() => setToast(''), 2600)
    return () => window.clearTimeout(timer)
  }, [toast])

  /**
   * 松手后读选区。
   *
   * 三条规则（主人 2026-09-14 定）：
   *   · **不按 Ctrl**：这一划就是新的全部选择（替换掉之前选的），**立刻弹输入框**；
   *   · **按住 Ctrl/Cmd**：把这一处**并进去** —— 这就是"多选不连续的几个地方"；
   *   · 按住 Ctrl 连选期间**不弹输入框**（主人指出："选完第一处就弹卡片"是错的），
   *     这段时间屏幕上**只有一个反馈**：被选中的段落带一层更深的底色
   *     （.ns-para-pending），**松开 Ctrl 之后再弹框**（见下面的 keyup 效果）。
   *     ⚠️ 不要在选区旁边飘提示文字 —— 主人 2026-09-14 否掉了：它就压在剧本上，
   *        会把接下来要划的那几行挡住。
   * 每一处都记成"段落范围"（连续跨段算一处），因为剧本段落是"一行一段"
   * 还是"多行一段"由 agent 决定。
   */
  const onScriptMouseUp = useCallback((e: MouseEvent<HTMLDivElement>): void => {
    /* 编辑模式下这一栏是文本框：不划词、不弹批注框（光标就是光标）。 */
    if (editMode) return
    const multi = e.ctrlKey || e.metaKey
    const releaseX = e.clientX
    const releaseY = e.clientY
    window.setTimeout(() => {
      const selection = window.getSelection()
      if (selection === null || selection.isCollapsed || selection.rangeCount === 0) return
      const range = selection.getRangeAt(0)
      const container = scriptRef.current
      if (container === null || !container.contains(range.commonAncestorContainer)) return
      const startEl = elementOf(range.startContainer, container)
      const endEl = elementOf(range.endContainer, container)
      if (startEl === null || endEl === null) return
      const startNo = Number(startEl.dataset.paragraph)
      const endNo = Number(endEl.dataset.paragraph)
      if (!Number.isInteger(startNo) || !Number.isInteger(endNo) || startNo < 1 || endNo < 1) return
      const paragraph = Math.min(startNo, endNo)
      const endParagraph = Math.max(startNo, endNo)
      const quote = selection.toString().trim()
      if (quote === '') return
      const region: AnnotationRegion = {
        paragraph,
        ...(endParagraph > paragraph ? { endParagraph } : {}),
        quote,
      }
      /* 批注框**跟着选区走**（主人 2026-09-13：不该固定在批注栏里）。
         用松手时的指针位置，多选时不会因为旧选区矩形而跳来跳去。 */
      const x = Math.min(Math.max(8, releaseX), Math.max(8, window.innerWidth - POPUP_W - 12))
      const y = Math.min(Math.max(8, releaseY + 14), Math.max(8, window.innerHeight - POPUP_H - 12))
      setPending(prev => {
        const list = multi && prev !== null ? [...prev.regions] : []
        const duplicate = list.some(r => r.paragraph === region.paragraph
          && r.endParagraph === region.endParagraph && r.quote === region.quote)
        if (!duplicate) list.push(region)
        /* 按住 Ctrl 时 open:false —— 框先不弹，等松开 Ctrl 再弹（主人 2026-09-14）。 */
        return { regions: list, x, y, open: !multi }
      })
      setProblem('')
      if (multi) {
        /* 多选期间把选区清掉，方便接着划下一处（否则第二处会被上一处的选区干扰）。 */
        window.getSelection()?.removeAllRanges()
      }
    }, 10)
  }, [editMode])

  /**
   * Ctrl 连选期间那几处覆盖的段号。
   *
   * 为什么需要它：连选时输入框是**不弹**的，而选区又被 removeAllRanges 清掉了 ——
   * 屏幕上就没有任何"我到底选了哪几处"的反馈。所以给这些段落单独加一层底色，
   * 这也是连选期间**唯一**的反馈（不再飘提示文字，见 onScriptMouseUp 的说明）。
   */
  const pendingParagraphs = useMemo(() => {
    const out = new Set<number>()
    if (pending === null) return out
    for (const region of pending.regions) {
      const end = region.endParagraph ?? region.paragraph
      for (let n = region.paragraph; n <= end; n += 1) out.add(n)
    }
    return out
  }, [pending])

  /* 松开 Ctrl/Cmd → 把输入框弹出来：多选结束。
     焦点不在窗口里时浏览器可能不给 keyup，所以另挂 blur 兜底，提示条本身也可以点开。 */
  useEffect(() => {
    if (pending === null || pending.open) return
    const openIt = (): void => setPending(prev => (prev === null || prev.open ? prev : { ...prev, open: true }))
    const onKeyUp = (e: KeyboardEvent): void => { if (e.key === 'Control' || e.key === 'Meta') openIt() }
    document.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', openIt)
    return () => {
      document.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', openIt)
    }
  }, [pending])

  const closePending = useCallback((): void => {
    setPending(null)
    setProblem('')
  }, [])

  const submitAnnotation = useCallback((): void => {
    if (pending === null || pending.regions.length === 0) return
    const text = problem.trim()
    if (text === '') { setToast('先写一下问题'); return }
    const seq = nextAnnotationSeq(anno.annotations)
    const created = makeAnnotation(seq, pending.regions, text)
    void anno.save([...anno.annotations, created]).then((ok) => {
      if (!ok) return
      setPending(null)
      setProblem('')
      window.getSelection()?.removeAllRanges()
      setToast('批注已保存')
    })
  }, [anno, pending, problem])

  /* 批注框开着时：Esc 关掉；点框外也关掉（点框内不关）。
     ⚠️ **在剧本栏里按下鼠标不算"点框外"** —— 那是要接着选下一处
     （Ctrl 多选时必须这样，否则一点就关、第二处就并不进来了）。
     ⚠️ 还按着 Ctrl 连选（open=false）时**不关**：那是选到一半，点别处多半是误触；
        想放弃按 Esc 就行。 */
  useEffect(() => {
    if (pending === null) return
    const open = pending.open
    const onKey = (e: KeyboardEvent): void => { if (e.key === 'Escape') closePending() }
    const onDown = (e: globalThis.MouseEvent): void => {
      if (!open) return
      const box = popRef.current
      if (box !== null && e.target instanceof Node && box.contains(e.target)) return
      if (e.target instanceof Element && e.target.closest('.ns-col-script') !== null) return
      closePending()
    }
    document.addEventListener('keydown', onKey)
    document.addEventListener('mousedown', onDown)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.removeEventListener('mousedown', onDown)
    }
  }, [pending, closePending])

  /** 跨集跳转：先切集，等这一集读出来再滚过去。 */
  const [pendingJump, setPendingJump] = useState<number[] | null>(null)

  /** 点批注卡 → 跳到它挂的那几处（剧本滚过去 + 原文高亮）；跨集也能跳。 */
  const jumpToParagraph = useCallback((episodeNo: number, regions: readonly AnnotationRegion[]): void => {
    const targets = paragraphsOfRegions(regions)
    const first = targets[0]
    if (first === undefined) return
    if (episode?.episode === episodeNo) {
      setPinnedParagraphs(targets)
      requestAnimationFrame(() => {
        scriptRef.current
          ?.querySelector(`[data-paragraph="${first}"]`)
          ?.scrollIntoView({ block: 'center', behavior: 'smooth' })
      })
      return
    }
    setPickEpisode(episodeNo)
    setPendingJump(targets)
  }, [episode])

  useEffect(() => {
    const first = pendingJump?.[0]
    if (pendingJump === null || first === undefined || ep.phase !== 'ready') return
    setPinnedParagraphs(pendingJump)
    setPendingJump(null)
    requestAnimationFrame(() => {
      scriptRef.current
        ?.querySelector(`[data-paragraph="${first}"]`)
        ?.scrollIntoView({ block: 'center', behavior: 'smooth' })
    })
  }, [pendingJump, ep.phase])

  /**
   * 选中剧本某几段 → 左侧原文**自动滚到对应位置**。
   *
   * 主人 2026-09-14 反馈："选择剧本后原文会高亮，但不会自动跳转原文对应位置"。
   * 只在**点选 / 定位**（`pinnedParagraphs`）时滚；悬停不滚 ——
   * 鼠标扫过段落时原文跟着乱跳会很难读。
   */
  useEffect(() => {
    if (pinnedParagraphs.length === 0) return
    let first = Number.POSITIVE_INFINITY
    for (const paragraph of ep.paragraphs) {
      if (!pinnedParagraphs.includes(paragraph.index)) continue
      for (const [a] of paragraph.sourceRanges ?? []) first = Math.min(first, a)
    }
    if (!Number.isFinite(first)) return
    requestAnimationFrame(() => {
      novelRef.current
        ?.querySelector(`[data-ln="${first}"]`)
        ?.scrollIntoView({ block: 'center', behavior: 'smooth' })
    })
  }, [pinnedParagraphs, ep.paragraphs])

  /**
   * 编辑模式下：**光标走到哪一段，左边原文就滚到对应位置**。
   *
   * 上面那条是"点选/定位"触发的，编辑时没有点选，所以原文栏一直不动 ——
   * 主人 2026-09-15 反馈："编辑模式下原文不会自动跳到光标所在的那一行"。
   *
   * ⚠️ 只在**目标行当前看不见**时才滚：否则光标每换一行都滚一次，
   *    正打着字屏幕一直跟着动，很难读。滚的时候**上方留两行**上下文
   *    （和提示词对照那边同一个口径）。`sourceRanges` 为空的段（新增内容）
   *    没有可滚的目标 —— 底栏会写"原文里没有对应（新增）"，这里什么也不做。
   */
  useEffect(() => {
    if (!editMode || caretParagraph === null) return
    const ranges = caretParagraph.sourceRanges
    if (ranges === null || ranges.length === 0) return
    const box = novelRef.current
    if (box === null) return
    const first = Math.min(...ranges.map(range => range[0]))
    const last = Math.max(...ranges.map(range => range[1]))
    const firstEl = box.querySelector<HTMLElement>(`[data-ln="${first}"]`)
    if (firstEl === null) return
    const lastEl = box.querySelector<HTMLElement>(`[data-ln="${last}"]`) ?? firstEl
    const boxTop = box.getBoundingClientRect().top
    /* getBoundingClientRect 是相对视口的，先换算成"相对滚动容器内容"的偏移。 */
    const top = firstEl.getBoundingClientRect().top - boxTop + box.scrollTop
    const bottom = lastEl.getBoundingClientRect().bottom - boxTop + box.scrollTop
    const alreadyVisible = top >= box.scrollTop && bottom <= box.scrollTop + box.clientHeight
    if (alreadyVisible) return
    const lineHeight = firstEl.offsetHeight > 0 ? firstEl.offsetHeight : 20
    box.scrollTo({ top: Math.max(0, top - lineHeight * 2), behavior: 'smooth' })
  }, [editMode, caretParagraph])

  /**
   * 删除一条批注。
   *
   * 批注是**按集一个文件**存的，所以"全部"模式下要写回**它所属那一集**的文件，
   * 不能一股脑写当前集。
   */
  const deleteOne = useCallback((episodeNo: number, id: string): void => {
    if (episode?.episode === episodeNo) {
      void anno.save(anno.annotations.filter(a => a.id !== id)).then((ok) => {
        if (ok) setToast('批注已删除')
      })
      return
    }
    const dir = version?.dir
    if (sessionId === undefined || sessionId === '' || dir === undefined) return
    const list = (allAnnotations[episodeNo] ?? []).filter(a => a.id !== id)
    /* 写回的是那一集**自己的有效版本**的批注文件（未必是当前看的这一版）。 */
    const otherTag = version?.episodes.find(item => item.episode === episodeNo)?.effective.tag ?? null
    void saveAnnotations(sessionId, dir, episodeNo, otherTag, list).then((result) => {
      if (result.ok) {
        setAllAnnotations(prev => ({ ...prev, [episodeNo]: result.annotations }))
        setToast('批注已删除')
      } else {
        setAllError(result.error)
      }
    })
  }, [anno, allAnnotations, episode, version, sessionId])

  /**
   * 这条批注挂的某一处还成不成立（设计文档 §7.3：**锚点失效是正常状态，不是错误**）。
   *
   * 判据只有一条：那一处引文还能不能在对应段落的正文里找到。找不到就标出来，
   * **不偷偷挪到同名文字上**。
   * 别的集的批注（"全部"模式）这里返回 `null`（不判）：没读它们的正文。
   *
   * ⚠️ 定义放在这里（而不是批注卡旁边）：组装下发指令时也要用它，
   *    而 `sendBatch` 比批注卡靠前 —— 放在后面会被"先用后声明"卡住。
   */
  const regionIsValid = useCallback((region: AnnotationRegion, episodeNo: number): boolean | null => {
    if (episode === null || episodeNo !== episode.episode || ep.phase !== 'ready') return null
    const from = ep.paragraphs[region.paragraph - 1]
    if (from === undefined || from.broken) return false
    const end = region.endParagraph === undefined ? region.paragraph : region.endParagraph
    const text = ep.paragraphs.slice(region.paragraph - 1, end).map(p => p.text).join('\n')
    return containsQuote(text, region.quote)
  }, [episode, ep])

  /** 这一轮要下发的条目（按集模式只有当前集；全部模式是所有集）。 */
  const sendItems = useMemo(() => {
    if (annoScope === 'episode') {
      return episode === null ? [] : anno.annotations.map(a => ({ episode: episode.episode, a }))
    }
    return Object.entries(allAnnotations)
      .flatMap(([ep, list]) => list.map(a => ({ episode: Number(ep), a })))
      .sort((x, y) => x.episode - y.episode
        || (x.a.regions?.[0]?.paragraph ?? 0) - (y.a.regions?.[0]?.paragraph ?? 0))
  }, [annoScope, episode, anno.annotations, allAnnotations])
  const sendCount = sendItems.length

  /** 这一版里"有人工改动"的集（有效版本是小版本的那些）。 */
  const manualEpisodes = useMemo(
    () => (version?.episodes ?? []).filter(entry => entry.effective.tag !== null).map(entry => entry.episode),
    [version],
  )
  /** 当前"按集/全部"范围里，有几集带人工改动。 */
  const manualInScope = annoScope === 'all'
    ? manualEpisodes.length
    : manualEpisodes.filter(no => no === episode?.episode).length

  /**
   * 组装"交给 agent"的那份指令（实施计划 §10）。
   *
   * ⚠️ 一份指令**同时**包含两件事：**人工已经改过的地方**（含历史记录文件路径）
   *    与**批注**（含"锚点已失效"的提醒），并显式写明"以最新版本为基线、
   *    旧版本只作参考"。为什么必须一起给：人工改过之后，批注的引文可能已经
   *    对不上正文了 —— agent 只看批注会改错地方，只看人工改动又会漏掉批注。
   *
   * 这里只负责"把这一轮牵涉到的集与批注凑齐"；**文案本身在
   * `shared/instruction.ts`**（纯函数 + 回归用例），免得这段最关键的话没人测。
   */
  const buildInstruction = useCallback((items: readonly { episode: number; a: Annotation }[]): string => {
    if (version === null) return ''
    const grouped = new Map<number, Annotation[]>()
    for (const item of items) {
      const list = grouped.get(item.episode) ?? []
      list.push(item.a)
      grouped.set(item.episode, list)
    }
    /* 这一轮牵涉到的集：有批注的 + 有人工改动的（都按当前范围筛）。 */
    const inScope = new Set<number>(grouped.keys())
    for (const no of manualEpisodes) {
      if (annoScope === 'all' || no === episode?.episode) inScope.add(no)
    }
    const episodeNos = [...inScope].sort((a, b) => a - b)
    if (episodeNos.length === 0) return ''
    const episodes: InstructionEpisode[] = [...inScope].sort((a, b) => a - b).map((no) => {
      const entry = version.episodes.find(e => e.episode === no)
      const list = grouped.get(no) ?? []
      return {
        episode: no,
        tag: entry?.effective.tag ?? null,
        annotations: list,
        staleIds: list
          .filter(a => (a.regions ?? []).some(r => regionIsValid(r, no) === false))
          .map(a => a.id),
      }
    })
    return renderInstruction({
      bookLine: novel.lines[0] ?? '',
      versionDir: version.dir,
      scope: annoScope,
      episodes,
      novelFile: novelPath(),
    })
  }, [version, episode, annoScope, novel.lines, manualEpisodes, regionIsValid])

  /**
   * 下发这一批（批注 + 人工改动）。
   *
   * ⚠️ 为什么是"复制到剪贴板"而不是直接写官方输入框：`shell.overlay` 这个席位
   * 拿不到 `inputActions`（只有 `conversation.*` 那些席位有），所以浮层里
   * 没法定向写官方输入框。主人粘一下即可（这是流程的下一步）。
   */
  const sendBatch = useCallback((): void => {
    const text = buildInstruction(sendItems)
    if (text === '') return
    void navigator.clipboard?.writeText(text).then(
      () => setToast(
        `已复制指令（${sendCount} 条批注${manualInScope === 0 ? '' : ` + ${manualInScope} 集人工改动`}）`
        + ' —— 粘到对话里发给 AI 即可',
      ),
      () => setToast('复制失败（浏览器拒绝剪贴板）'),
    )
  }, [buildInstruction, sendItems, sendCount, manualInScope])

  /* ── 窗口几何（拖动 / 缩放 / 最小化 / 最大化）────────────────────────── */
  const geo = useWorkbenchGeometry()
  const wbRef = geo.ref
  const minBtnRef = useRef<HTMLButtonElement | null>(null)
  const isMin = geo.mode === 'min'
  /** 收起成胶囊时的高度：原来 24 太小，找不到也点不着（主人反馈）。
      36 = 样式里圆角 18 的两倍，正好是一枚完整的胶囊。 */
  const PILL_H = 36

  /* ── 键盘左右翻集 ──────────────────────────────────────────────────────
     ⚠️ 只在"没在输入/编辑"时生效：
       · 焦点在 input / textarea / select / 可编辑元素里 → 让给它们（别抢左右键）；
       · 批注框开着 → 让给批注框（主人特意提醒过"不要和编辑批注冲突"）。 */
  useEffect(() => {
    /* 编辑模式下**整体关掉**左右键翻集：点空白处按方向键也不该跳集。 */
    if (isMin || editMode) return
    const onKey = (e: KeyboardEvent): void => {
      if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return
      if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return
      const target = e.target as HTMLElement | null
      if (target?.closest('input, textarea, select, [contenteditable="true"]') != null) return
      if (pending !== null) return
      const next = e.key === 'ArrowLeft' ? episodeNav.prev : episodeNav.next
      if (next === undefined) return
      e.preventDefault()
      setPickEpisode(next.episode)
    }
    document.addEventListener('keydown', onKey)
    return () => { document.removeEventListener('keydown', onKey) }
  }, [episodeNav, pending, isMin, editMode])

  const startDrag = useCallback((e: MouseEvent<HTMLElement>, dragMode: 'move' | 'h' | 'w' | 'corner'): void => {
    const el = wbRef.current
    if (el === null) return
    const session = geo.beginDrag(el.getBoundingClientRect(), e.clientX, e.clientY, dragMode)
    document.body.classList.add(dragMode === 'move' ? 'ns-dragging' : 'ns-resizing')
    const onMove = (ev: globalThis.MouseEvent): void => session.apply(ev.clientX, ev.clientY)
    const onUp = (): void => {
      document.body.classList.remove('ns-dragging', 'ns-resizing')
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
      session.finish()
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
    e.preventDefault()
  }, [geo, wbRef])

  /* ── 列宽 ──────────────────────────────────────────────────────────── */
  const colsRef = useRef<HTMLDivElement | null>(null)
  const [srcW, setSrcW] = useState(300)
  const [annoW, setAnnoW] = useState(300)

  const startColDrag = useCallback((e: MouseEvent<HTMLDivElement>, side: 'src' | 'anno'): void => {
    const startX = e.clientX
    const startW = side === 'src' ? srcW : annoW
    const total = colsRef.current?.clientWidth ?? 0
    const other = side === 'src' ? annoW : srcW
    const max = Math.max(MIN_SIDE, total - other - MIN_MID - 22)
    document.body.classList.add('ns-colresizing')
    const onMove = (ev: globalThis.MouseEvent): void => {
      const d = ev.clientX - startX
      const next = Math.min(Math.max(MIN_SIDE, startW + (side === 'src' ? d : -d)), max)
      if (side === 'src') setSrcW(next)
      else setAnnoW(next)
    }
    const onUp = (): void => {
      document.body.classList.remove('ns-colresizing')
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  }, [srcW, annoW])

  /* ── 窗口样式 ──────────────────────────────────────────────────────── */
  const wbStyle: CSSProperties = isMin
    ? {
        ...(geo.pillPos === null
          ? { right: geo.minRight ?? 12, top: geo.minTop ?? 56, width: 'auto' }
          : { left: geo.pillPos.x, top: geo.pillPos.y, width: 'auto' }),
        height: PILL_H,
      }
    : { left: geo.geom.x, top: geo.geom.y, width: geo.geom.w, height: geo.geom.h }

  /* ── 顶部提示（把所有"读不到 / 对不上"集中到一处）──────────────────── */
  const notices: string[] = []
  if (wb.error !== '') notices.push(`扫描出错：${wb.error}`)
  notices.push(...scan.issues)
  if (ep.error !== '') notices.push(ep.error)
  notices.push(...ep.issues.map((i: Issue) => `${i.where}：${i.message}`))
  if (anno.error !== '') notices.push(`批注：${anno.error}`)
  if (novel.error !== '') notices.push(novel.error)
  if (sessionSource === 'fallback') notices.push('当前没有选中会话，借用的是工作区里的另一个会话；想更准请切到剧本所在工作区的会话。')

  const episodeLabel = episode === null ? '—' : `${episode.episode}`
  const versionLabel = version === null ? '—' : `v${version.version}`
  /** 这一集自己的版本标签（`v2.2（人工）` / `v2`）；没选中集时是空串。 */
  const episodeVersionLabel = episode === null || version === null
    ? ''
    : effectiveLabel(episode, version.version)
  /** 选集下拉里每一项的文案：基线显示 `第 3 集 · v2`，人工版显示 `第 1 集 · v2.2（人工）`。 */
  const episodeOptionLabel = (entry: EpisodeEntry): string =>
    version === null ? `第 ${entry.episode} 集` : `第 ${entry.episode} 集 · ${effectiveLabel(entry, version.version)}`

  /**
   * 一张批注卡。
   *
   * @param a - 批注内容（段落范围从 `a.paragraph` / `a.endParagraph` 取）。
   * @param episodeNo - 给了就显示"第 N 集"（"全部"模式用），并据此定位 / 删除。
   */
  const annotationCard = (a: Annotation, episodeNo?: number): ReactNode => {
    const episodeOfCard = episodeNo ?? episode?.episode ?? 0
    /* 防御：`regions` 万一缺失（例如老宿主返回老格式），也不能让整个工作台崩掉。 */
    const regions = a.regions ?? []
    const first = regions[0]
    /* 锚点已失效的条数：只判**当前这一集**（别的集没读正文）。 */
    const staleCount = regions.filter(r => regionIsValid(r, episodeOfCard) === false).length
    return (
      <div key={a.id} className={`ns-acard${a.done ? ' ns-acard-done' : ''}`}>
        <div className="ns-acard-r1">
          {episodeNo === undefined ? null : <span className="ns-tag">第 {episodeNo} 集</span>}
          <span className="ns-tag">{first === undefined ? '（没有区域）' : regionLabel(first)}</span>
          {regions.length > 1 ? <span className="ns-tag">共 {regions.length} 处</span> : null}
          {staleCount > 0 ? <span className="ns-tag ns-tag-stale">锚点已失效 ×{staleCount}</span> : null}
          <span className={`ns-tag${a.done ? ' ns-tag-done' : ''}`}>
            {a.done ? `已处理${a.resolvedIn === null ? '' : ` · ${a.resolvedIn}`}` : '未处理'}
          </span>
          <div className="ns-spacer" />
          <button
            type="button"
            className="ns-x"
            title={episodeNo === undefined ? '定位到这些地方' : `定位到第 ${episodeNo} 集`}
            onClick={() => jumpToParagraph(episodeOfCard, a.regions)}
          >
            ◎
          </button>
          <button
            type="button"
            className="ns-x"
            title="删除这条批注"
            onClick={() => deleteOne(episodeOfCard, a.id)}
          >
            ✕
          </button>
        </div>
        {regions.map((region, index) => {
          const valid = regionIsValid(region, episodeOfCard)
          return (
            <div
              key={`${region.paragraph}-${index}`}
              className={`ns-acard-q${valid === false ? ' ns-acard-q-stale' : ''}`}
            >
              {/* ⚠️ 锚点失效时，这个段号是**改之前那一版**的段号（现在多半已经指到别的段上了），
                  所以明写"旧版段号"，免得看成"正文里的第 N 段"。 */}
              <span className="ns-acard-ln">
                {regionLabel(region)}{valid === false ? '（旧版段号）' : ''}
              </span>
              {valid === false ? <span className="ns-tag-stale">引文已找不到</span> : null}
              “{region.quote.length > 60 ? `${region.quote.slice(0, 60)}…` : region.quote}”
            </div>
          )
        })}
        <div className="ns-why">{a.problem}</div>
        <div className="ns-ameta">{a.id}</div>
      </div>
    )
  }

  return (
    <>
      <div
        className={`ns-workbench${isMin ? ' ns-min' : ''}`}
        ref={wbRef}
        style={wbStyle}
      >
        <div
          className="ns-wb-hd"
          onMouseDown={(e) => {
            /* 交互控件必须放过：这个 handler 末尾会 preventDefault（拖窗口用），
               而 select/input 的 mousedown 默认行为正是"打开下拉 / 聚焦"。 */
            if ((e.target as HTMLElement).closest('button, select, input, textarea, a, [contenteditable="true"]')) return
            const el = wbRef.current
            if (el === null) return
            if (isMin) {
              const session = geo.beginPillDrag(el.getBoundingClientRect(), e.clientX, e.clientY)
              const down = { x: e.clientX, y: e.clientY }
              let moved = false
              const onMove = (ev: globalThis.MouseEvent): void => {
                if (!moved && Math.abs(ev.clientX - down.x) + Math.abs(ev.clientY - down.y) > 4) moved = true
                if (moved) session.apply(ev.clientX, ev.clientY)
              }
              const onUp = (): void => {
                document.removeEventListener('mousemove', onMove)
                document.removeEventListener('mouseup', onUp)
              }
              document.addEventListener('mousemove', onMove)
              document.addEventListener('mouseup', onUp)
              e.preventDefault()
              return
            }
            if (geo.mode === 'max') return
            startDrag(e, 'move')
          }}
        >
          <span className="ns-grip" aria-hidden>⋮⋮</span>
          <span className="ns-t">剧本批注</span>
          <span className="ns-meta">
            {scan.phase === 'missing'
              ? '这个工作区还没登记'
              : `${versionLabel} · 第 ${episodeLabel} 集${effTag === null ? '' : ` · ${episodeVersionLabel}`}`}
          </span>
          <div className="ns-spacer" />
          {!isMin && scan.versions.length > 0
            ? (
              <>
                {/* 上一集 / 下一集：放在**版本选择左边**（主人指定的位置），
                    左右方向键也能翻（见上面那段 keydown 监听）。 */}
                <button
                  type="button"
                  className="ns-x"
                  title="上一集（←）"
                  disabled={episodeNav.prev === undefined}
                  onClick={() => { if (episodeNav.prev !== undefined) pickEpisodeGuarded(episodeNav.prev.episode) }}
                >
                  ◀
                </button>
                <button
                  type="button"
                  className="ns-x"
                  title="下一集（→）"
                  disabled={episodeNav.next === undefined}
                  onClick={() => { if (episodeNav.next !== undefined) pickEpisodeGuarded(episodeNav.next.episode) }}
                >
                  ▶
                </button>
                <select
                  className="ns-sel"
                  title="选版本"
                  value={version?.version ?? ''}
                  onChange={(e) => pickVersionGuarded(e.target.value)}
                >
                  {scan.versions.map(v => (
                    <option key={v.version} value={v.version}>
                      v{v.version}（{v.episodes.length} 集）
                    </option>
                  ))}
                </select>
                <select
                  className="ns-sel"
                  title="选集"
                  value={episode === null ? '' : String(episode.episode)}
                  onChange={(e) => pickEpisodeGuarded(Number(e.target.value))}
                  disabled={(version?.episodes.length ?? 0) === 0}
                >
                  {(version?.episodes ?? []).map(x => (
                    <option key={x.episode} value={String(x.episode)}>{episodeOptionLabel(x)}</option>
                  ))}
                </select>
              </>
            )
            : null}
          {!isMin
            ? <button type="button" className="ns-x" title="刷新" onClick={() => { wb.reload(); ep.reload(); anno.reload() }}>⟳</button>
            : null}
          {/* 放大按钮：收起成胶囊时**不显示** —— 胶囊里只留"展开"这一颗，
              多一颗按钮既没用、又把胶囊撑得又宽又乱。 */}
          {!isMin
            ? (
              <button
                type="button"
                className="ns-x"
                title={geo.mode === 'max' ? '还原为默认大小' : '放大（占满整个界面）'}
                onClick={geo.toggleMax}
              >
                {geo.mode === 'max' ? '⤡' : '⛶'}
              </button>
            )
            : null}
          <button
            ref={minBtnRef}
            type="button"
            className="ns-x"
            title={isMin ? '展开工作台' : '收起成一枚小胶囊'}
            onClick={() => geo.toggleMin(minBtnRef.current)}
          >
            {isMin ? '▣' : '—'}
          </button>
        </div>

        {/* 缩放手柄：右边缘 / 下边缘 / 右下角。原来漏了，窗口大小拉不动
            （主人 2026-09-14："当前无法调整浮窗大小"）。
            样式在 styles.ts 的 `.ns-rs*`，拖拽走 geometry 的 'w' / 'h' / 'corner'。 */}
        {!isMin
          ? (
            <>
              <div className="ns-rs ns-rs-r" title="拖动调整宽度" onMouseDown={e => startDrag(e, 'w')} />
              <div className="ns-rs ns-rs-b" title="拖动调整高度" onMouseDown={e => startDrag(e, 'h')} />
              <div className="ns-rs ns-rs-br" title="拖动调整大小" onMouseDown={e => startDrag(e, 'corner')} />
            </>
          )
          : null}

        {!isMin && notices.length > 0
          ? (
            <div className="ns-issues ns-issues-err" title={notices.join('\n')}>
              <span className="ns-issues-t">有问题 {notices.length} 条</span>
              <span className="ns-issues-m">{notices[0]}</span>
              {notices.length > 1 ? <span className="ns-issues-n">悬停看全部</span> : null}
            </div>
          )
          : null}

        {!isMin && scan.phase === 'missing'
          ? (
            <div className="ns-onboard">
              <div className="ns-onboard-t">这个工作区还没登记</div>
              <div className="ns-page-d">
                工作台只读 <b>剧本工作台/</b> 这个固定目录，它自己不认识文件、也不解析剧本格式。
                把下面这段话发给对话里的 AI，它建好目录、拷好原文、一集一集登记完，这里就会出现原文与剧本对照。
              </div>
              <pre className="ns-copy">{REGISTER_PROMPT}</pre>
              <div className="ns-onboard-act">
                <button
                  type="button"
                  className="ns-btn ns-btn-primary"
                  onClick={() => {
                    void navigator.clipboard?.writeText(REGISTER_PROMPT).then(
                      () => setToast('已复制 —— 粘到对话里发给 AI 即可'),
                      () => setToast('复制失败（浏览器拒绝剪贴板）'),
                    )
                  }}
                >
                  复制这段话
                </button>
                <button type="button" className="ns-btn" onClick={() => wb.reload()}>我已经建好了，重新扫描</button>
              </div>
            </div>
          )
          : null}

        {!isMin && scan.phase === 'empty'
          ? (
            <div className="ns-onboard">
              <div className="ns-onboard-t">剧本工作台里还没有版本</div>
              <div className="ns-page-d">
                目录建好了，但里面还没有 <b>v1/</b>。让 AI 把第 1 集登记进来（它要用 novel_script_write_episode 工具）。
              </div>
              <div className="ns-onboard-act">
                <button type="button" className="ns-btn" onClick={() => wb.reload()}>重新扫描</button>
              </div>
            </div>
          )
          : null}

        {!isMin && scan.phase === 'ready'
          ? (
            <div className="ns-wb-cols" ref={colsRef} onMouseUp={onScriptMouseUp}>
              {/* ① 小说原文 */}
              <div className="ns-col ns-col-src" style={{ width: srcW }}>
                <div className="ns-col-hd">
                  <span>小说原文</span>
                  <div className="ns-spacer" />
                  <span className="ns-sub">
                    {novel.phase === 'ready' ? `${novel.lines.length} 行` : novel.phase === 'loading' ? '读取中…' : '—'}
                    {ep.novelRange === null ? '' : ` · 本集 L${ep.novelRange[0]}—L${ep.novelRange[1]}`}
                  </span>
                </div>
                <div className="ns-col-bd" ref={novelRef}>
                  {/* 本集覆盖范围：一根连续竖条（见上面 coverBar 的说明） */}
                  {coverBar === null
                    ? null
                    : <div className="ns-coverbar" style={{ top: coverBar.top, height: coverBar.height }} aria-hidden />}
                  {novel.phase !== 'ready'
                    ? <div className="ns-empty">{novel.phase === 'loading' ? '正在读取原文…' : novel.error || '没有原文'}</div>
                    : novel.lines.map((text, index) => {
                      const ln = index + 1
                      const cls = `ns-sline${highlightLines.has(ln) ? ' ns-hl' : ''}`
                      return (
                        <div key={ln} data-ln={ln} className={cls}>
                          <span className="ns-ln">{ln}</span>
                          <span className="ns-stx">{text}</span>
                        </div>
                      )
                    })}
                </div>
              </div>

              <div className="ns-split" onMouseDown={(e) => startColDrag(e, 'src')} title="拖动调整宽度" />

              {/* ② 剧本（按段落渲染，不判断段落类型） */}
              <div className="ns-col ns-col-script">
                <div className="ns-col-hd">
                  <span>第 {episodeLabel} 集剧本 · {versionLabel}</span>
                  {effTag === null ? null : <span className="ns-tag">{effTag}（人工）</span>}
                  <div className="ns-spacer" />
                  <span className="ns-sub">
                    {editMode
                      ? (draftDirty ? '编辑中 · 有未保存改动' : '编辑中')
                      : ep.phase === 'ready'
                        ? `${ep.totalLines} 行 · ${ep.paragraphs.length} 段`
                        : ep.phase === 'loading' ? '读取中…' : '—'}
                  </span>
                  {/* 模式开关：关 = 标注（现状），开 = 人工编辑（整集一个编辑面，只显示行号）。 */}
                  <button
                    type="button"
                    className={`ns-toggle${editMode ? ' ns-toggle-on' : ''}`}
                    disabled={!editMode && !canEdit}
                    title={editMode
                      ? '退出编辑模式（回到标注）'
                      : canEdit
                        ? '直接编辑这一集：保存会写成新小版本，老版本一个字节都不动'
                        : structureOk
                          ? '只有最新的大版本才能直接编辑（老版本只读）'
                          : '清单与正文对不上，先让 agent 修好再编辑'}
                    aria-pressed={editMode}
                    onClick={toggleEditMode}
                  >
                    <span className="ns-toggle-dot" />
                    <span>{editMode ? '编辑中' : '直接编辑'}</span>
                  </button>
                </div>
                {editMode && draft !== null
                  ? (
                    <div className="ns-edit">
                      <div className="ns-edit-body">
                      <div className="ns-edit-gut" ref={gutRef} aria-hidden>
                        {draftLines.map((_, index) => <div key={index} className="ns-edit-ln">{index + 1}</div>)}
                      </div>
                      <textarea
                        ref={taRef}
                        className="ns-edit-ta"
                        value={draft.text}
                        spellCheck={false}
                        wrap="off"
                        aria-label="这一集剧本正文"
                        /*
                         * ⚠️ 每个 handler 都要**先把值取出来**（`const text = …`），再交给
                         * `mutateDraft` 的回调。React 在事件派发结束之后会把合成事件的
                         * `currentTarget` 置成 null，而 `setState` 的回调是**稍后**才跑的 ——
                         * 2026-09-15 就因此在 `onCompositionStart` 里踩过
                         * `Cannot read properties of null (reading 'value')`：
                         * 打字打到一半整个工作台被错误边界掀掉。它"不是每次都犯"，
                         * 是因为 React 有时会立刻执行这次更新（eager state），那时还来得及。
                         */
                        onChange={(e) => {
                          const text = e.target.value
                          const now = Date.now()
                          mutateDraft(cur => ({
                            ...cur, text,
                            snap: snapshotReducer(cur.snap, { kind: 'input', text, nowMs: now }),
                          }))
                        }}
                        onCompositionStart={() => {
                          const text = taRef.current?.value ?? ''
                          const now = Date.now()
                          mutateDraft(cur => ({
                            ...cur,
                            snap: snapshotReducer(cur.snap, { kind: 'compositionStart', text, nowMs: now }),
                          }))
                        }}
                        onCompositionEnd={() => {
                          const text = taRef.current?.value ?? ''
                          const now = Date.now()
                          mutateDraft(cur => ({
                            ...cur, text,
                            snap: snapshotReducer(cur.snap, {
                              kind: 'compositionEnd', text, at: clockOf(now), nowMs: now,
                            }),
                          }))
                        }}
                        onBlur={() => {
                          const text = taRef.current?.value ?? ''
                          const now = Date.now()
                          mutateDraft(cur => ({
                            ...cur, text,
                            snap: snapshotReducer(cur.snap, { kind: 'blur', text, at: clockOf(now), nowMs: now }),
                          }))
                        }}
                        onScroll={() => {
                          const ta = taRef.current
                          const gut = gutRef.current
                          if (ta !== null && gut !== null) gut.scrollTop = ta.scrollTop
                        }}
                        onSelect={updateCaretFromRef}
                        onClick={updateCaretFromRef}
                        onKeyUp={updateCaretFromRef}
                      />
                      </div>
                      <div className="ns-edit-bar">
                        <span className="ns-edit-where">
                          {caretParagraph === null
                            ? '光标不在正文里'
                            : `第 ${caretParagraph.index} 段 · ${
                              caretParagraph.sourceRanges === null
                                ? '原文里没有对应（新增）'
                                : `→ 原文 ${caretParagraph.sourceRanges.map(r => `L${r[0]}—L${r[1]}`).join('、')}`
                            }${caretParagraph.needsReview ? ' · 待复核' : ''}`}
                        </span>
                        <div className="ns-spacer" />
                        <button
                          type="button"
                          className="ns-btn"
                          disabled={!draftDirty || savingDraft}
                          onClick={discardDraft}
                        >
                          放弃
                        </button>
                        <button
                          type="button"
                          className="ns-btn ns-btn-primary"
                          disabled={!draftDirty || savingDraft}
                          onClick={() => { void saveDraft() }}
                        >
                          {savingDraft ? '保存中…' : '保存'}
                        </button>
                      </div>
                    </div>
                  )
                  : (
                <div className="ns-col-bd" ref={scriptRef}>
                  {ep.phase !== 'ready'
                    ? <div className="ns-empty">{ep.phase === 'loading' ? '正在读取这一集…' : (ep.error || '读不到这一集')}</div>
                    : ep.paragraphs.map(p => (
                      <div
                        key={p.index}
                        data-paragraph={p.index}
                        className={`ns-para${isPinned(p.index) ? ' ns-para-pinned' : ''}${pendingParagraphs.has(p.index) ? ' ns-para-pending' : ''}${p.broken ? ' ns-para-broken' : ''}`}
                        onMouseEnter={() => setHoverParagraph(p.index)}
                        onMouseLeave={() => setHoverParagraph(prev => (prev === p.index ? null : prev))}
                        onClick={() => setPinnedParagraphs(prev => (
                          prev.length === 1 && prev[0] === p.index ? [] : [p.index]
                        ))}
                        title={p.sourceRanges === null ? '原文里没有对应（新增）' : `对应原文 ${p.sourceRanges.map(r => `L${r[0]}—L${r[1]}`).join('、')}`}
                      >
                        <span className="ns-para-no">{p.index}</span>
                        <span className="ns-para-tx">
                          {p.broken
                            ? <span className="ns-para-bad">（这一段清单坏了，画不出来）</span>
                            : p.lines.map((line, i) => <span key={i} className="ns-para-line">{line}</span>)}
                        </span>
                        <span className={`ns-para-src${p.sourceRanges === null ? ' ns-para-new' : ''}`}>
                          {p.broken ? '—' : p.sourceRanges === null ? '新增' : `L${p.sourceRanges[0]?.[0] ?? '?'}`}
                        </span>
                      </div>
                    ))}
                  </div>
                  )}
              </div>

              <div className="ns-split" onMouseDown={(e) => startColDrag(e, 'anno')} title="拖动调整宽度" />

              {/* ③ 批注 */}
              <div className="ns-col ns-col-anno" style={{ width: annoW }}>
                <div className="ns-col-hd">
                  <span>批注</span>
                  <div className="ns-spacer" />
                  {/* 按集看 / 全部看：批注是按集一个文件存的，"全部"会把这一版
                      每一集的批注都读回来并标出集号。 */}
                  <span className="ns-seg">
                    <button
                      type="button"
                      className={annoScope === 'episode' ? 'ns-seg-on' : ''}
                      title="只看当前这一集"
                      onClick={() => setAnnoScope('episode')}
                    >
                      按集
                    </button>
                    <button
                      type="button"
                      className={annoScope === 'all' ? 'ns-seg-on' : ''}
                      title="看这一版所有集的批注"
                      onClick={() => setAnnoScope('all')}
                    >
                      全部
                    </button>
                  </span>
                  <span className="ns-sub">
                    {annoScope === 'all' ? `${allCount} 条` : `${anno.annotations.length} 条`}
                  </span>
                </div>
                <div className="ns-col-bd">
                  <div className="ns-empty">
                    在剧本里划选一段文字（一次只能选一段里的），
                    批注框会在选区下方浮出来。
                  </div>

                  {annoScope === 'episode'
                    ? anno.annotations.map(a => annotationCard(a))
                    : (
                      <>
                        {allError === '' ? null : <div className="ns-empty">读批注出错：{allError}</div>}
                        {(version?.episodes ?? []).map(item => {
                          const list = allAnnotations[item.episode] ?? []
                          if (list.length === 0) return null
                          return (
                            <div key={item.episode}>
                              <div className="ns-anno-group">第 {item.episode} 集 · {list.length} 条</div>
                              {list.map(a => annotationCard(a, item.episode))}
                            </div>
                          )
                        })}
                        {allCount === 0 && allError === '' ? <div className="ns-empty">这一版还没有任何批注。</div> : null}
                      </>
                    )}
                </div>

                {/* 下发：流程的下一步。浮层写不进官方输入框，所以是"复制指令"。
                    指令里**同时**含批注与人工改动（见 buildInstruction）。 */}
                <div className="ns-col-foot">
                  <button
                    type="button"
                    className="ns-btn ns-btn-primary"
                    disabled={sendCount === 0 && manualInScope === 0}
                    title={sendCount === 0 && manualInScope === 0
                      ? '还没有批注，也没有人工改动'
                      : '把批注与人工改动整理成一份指令，复制到剪贴板'}
                    onClick={sendBatch}
                  >
                    {manualInScope === 0 ? `下发 ${sendCount} 条批注` : `下发 ${sendCount} 条批注 + ${manualInScope} 集人工改动`}
                  </button>
                  <div className="ns-foot-hint">
                    {annoScope === 'all' ? '这一版所有集一起下发' : '复制成指令 → 粘到对话里发给 AI'}
                  </div>
                </div>
              </div>
            </div>
          )
          : null}

        {toast === '' ? null : <div className="ns-toast">{toast}</div>}
      </div>

      {/* ══ 批注框：**跟着选区浮出来**（贴在选区下方，夹在视口内）══════════
          为什么不做成批注栏里的固定面板：主人指出"位置不应该固定在这里，
          而是根据选择位置而定"。这里只写问题，**不需要选类型**。 */}
      {pending !== null && pending.open && !isMin
        ? (
          <div
            className="ns-pop2"
            ref={popRef}
            style={{ left: pending.x, top: pending.y, pointerEvents: 'auto' }}
          >
            <div className="ns-pop2-hd">
              <span>
                {pending.regions.length > 1
                  ? `已选 ${pending.regions.length} 处`
                  : (pending.regions[0] === undefined ? '没有选中' : regionLabel(pending.regions[0]))}
              </span>
              <div className="ns-spacer" />
              <span className="ns-pop2-hint">按住 Ctrl 可再选别处</span>
              <button type="button" className="ns-x" title="关掉" onClick={closePending}>✕</button>
            </div>
            <div className="ns-pop2-list">
              {pending.regions.map((region, index) => (
                <div key={`${region.paragraph}-${index}`} className="ns-pop2-q">
                  <span className="ns-acard-ln">{regionLabel(region)}</span>
                  “{region.quote}”
                </div>
              ))}
            </div>
            <textarea
              className="ns-editor-t"
              placeholder="这里有什么问题？（一句话就行）"
              value={problem}
              autoFocus
              onChange={e => setProblem(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) submitAnnotation()
                if (e.key === 'Escape') closePending()
              }}
            />
            <div className="ns-editor-act">
              <button type="button" className="ns-btn" onClick={closePending}>取消</button>
              <div className="ns-spacer" />
              <button type="button" className="ns-btn ns-btn-primary" disabled={anno.saving} onClick={submitAnnotation}>
                {anno.saving ? '保存中…' : '加入批注'}
              </button>
            </div>
          </div>
        )
        : null}
    </>
  )
}

/**
 * 从选区的一个端点往上找"带 data-paragraph 的那个元素"。
 * @param node - 选区的 startContainer / endContainer。
 * @param within - 剧本栏容器（防止把别处的选区算进来）。
 */
function elementOf(node: Node, within: HTMLElement): HTMLElement | null {
  let el: HTMLElement | null = node instanceof HTMLElement ? node : node.parentElement
  while (el !== null && el !== within) {
    if (el.dataset.paragraph !== undefined) return el
    el = el.parentElement
  }
  return null
}
